// Hindi for sages/vishvamitra.js — keys are HI.hash(<Telugu string>). Written by tools/hi_write.js.
HI.add({
 "24415670": "मिथिला में विश्वामित्र ही {janaka|जनक} से कहते हैं कि बालकों को शिवजी का महान धनुष दिखाया जाए। राम उसे उठाते हैं, उस पर डोरी चढ़ाते हैं और उसे तोड़ देते हैं, और {sita|सीता} को जीत लेते हैं। चारों विवाहों तक विश्वामित्र वहीं रहते हैं — और फिर, रामायण सीधे-सीधे कहती है, वे दोनों राजाओं से विदा लेकर उत्तर के पर्वतों की ओर चले गए। राम के साथ उनका काम पूरा हो चुका था।",
 "43733096": "“मैं अपने सबसे बड़े बेटे को कभी नहीं बेचूँगा,” ऋचीक ने कहा। “और मैं अपने सबसे छोटे बेटे शुनक को कभी नहीं बेचूँगी,” उनकी पत्नी ने कहा। तब मँझला बेटा, {shunahshepa|शुनःशेप}, धीरे से बोला: “पिताजी बड़े को नहीं बेचेंगे, माँ छोटे को नहीं बेचेंगी। तो लगता है बिकने के लिए मँझला ही बचा है। राजन, मुझे ले चलिए।” अंबरीष ने एक लाख गायें, एक करोड़ सोने के सिक्के और रत्नों के ढेर दिए, बालक को अपने रथ में बिठाया और तेज़ी से चल पड़े।",
 "62399749": "उन्होंने अपनी सौ की सौ बेटियों का विवाह ब्रह्मदत्त से कर दिया, जो चूली ऋषि और गंधर्व स्त्री सोमदा के पुत्र, एक ज्ञानी राजा थे। जैसे ही ब्रह्मदत्त ने हर दुल्हन का हाथ थामा, उसका शरीर फिर से सीधा और सुंदर हो गया।",
 "71939032": "शबला का दिल टूट गया। “क्या महात्मा वसिष्ठ ने मुझे छोड़ दिया है? मैंने क्या गलती की है कि राजा के ये सेवक मुझे मेरे प्यारे स्वामी से दूर खींचकर ले जा रहे हैं?” फिर पूरा ज़ोर लगाकर उसने राजा के सैकड़ों आदमियों को झटक दिया और हवा की तरह दौड़कर वसिष्ठ के पास लौट आई। वह उनके सामने खड़ी होकर रोने लगी, बादल की गरज जैसी आवाज़ में रँभाती हुई।",
 "71944954": "विश्वामित्र कुत्ते का मांस लेकर वन में अपनी पत्नी के पास लौटे। उन्होंने उसे तुरंत नहीं खाया। उन्होंने उसे यज्ञ की विधि से पकाया, और पहले उसका एक भाग अग्नि में इंद्र, अग्नि और देवताओं को अर्पित किया। उसी क्षण इंद्र ने प्रसन्न होकर वर्षा बरसाई — और उस वर्षा ने धरती के सारे पौधों और प्राणियों को फिर से जीवित कर दिया, और अकाल समाप्त हो गया। विश्वामित्र ने अपनी तपस्या से पवित्र होकर अपने किए का पाप जला डाला।",
 "95472677": "उन्होंने पहले देवताओं को अर्पित किया; इंद्र ने वर्षा भेजी और अकाल समाप्त हो गया। यही आपद्धर्म है।",
 "62481ea1": "कुश के वंश में जन्म",
 "a0fdf315": "ऋषि बनने से बहुत पहले विश्वामित्र एक राजा थे — और राजाओं के वंश से आए थे। उनके परदादा {kusha|कुश} थे, जो स्वयं ब्रह्मा के पुत्र थे। कुश एक शक्तिशाली राजा थे, धर्म और तपस्या में लगे रहते थे, और उनके चार पुत्र थे: कुशांब, {kushanabha|कुशनाभ}, असूर्तरजस और वसु। हर पुत्र ने अपना एक महान नगर बसाया — कौशांबी, महोदय, धर्मारण्य और गिरिव्रज।",
 "6df499d7": "कुशनाभ महोदय पर राज करते थे। अप्सरा घृताची से उनकी सौ बेटियाँ हुईं, एक से बढ़कर एक सुंदर। एक दिन जब वे एक बगीचे में गा रही थीं और नाच रही थीं, तब पवन देवता वायु ने उन्हें देखा और उन्हें पाना चाहा। “मुझसे विवाह कर लो,” उन्होंने कहा, “तो तुम कभी बूढ़ी नहीं होगी; देवताओं जितना जियोगी।” राजकुमारियाँ उन पर हँस पड़ीं। “वायुदेव, हम आपकी शक्ति जानती हैं। पर हमारा विवाह किससे होगा, यह हमारे पिता तय करते हैं — न आप, न हम स्वयं।”",
 "a4c72a80": "क्रोधित होकर वायु उनके शरीरों में घुस गए और उन्हें टेढ़ा कर दिया, जिससे सौ की सौ कुबड़ी हो गईं। रोती हुई वे अपने पिता के पास गईं। पर जब कुशनाभ ने सुना कि उनकी बेटियों ने देवता को बदले में श्राप देने के बजाय क्षमा कर दिया, तो उन्हें अपनी बेटियों पर गर्व हुआ। “क्षमा स्त्रियों और पुरुषों दोनों का गहना है,” उन्होंने कहा। “क्षमा धर्म है, क्षमा सत्य है, क्षमा ही संसार को जोड़े रखती है।”",
 "63fc3c3b": "इसी कथा के कारण महोदय का नाम कान्यकुब्ज पड़ा — “कुबड़ी कन्याओं का नगर”। आज वह उत्तर प्रदेश का कन्नौज है।",
 "7ee28896": "कुशनाभ का कोई पुत्र नहीं था, इसलिए उन्होंने पुत्र के लिए यज्ञ किया, और उनके यहाँ एक पुत्र जन्मा: {gadhi|गाधि}। बड़े होकर गाधि ने कान्यकुब्ज पर राज किया। उनकी एक बेटी थी, {satyavati|सत्यवती}, और जब वह विवाह योग्य हुई, तो भृगु कुल के एक वृद्ध ऋषि {richika|ऋचीक} आए और उसका हाथ माँगा।",
 "e83ed0c2": "गाधि अपनी बेटी को एक गरीब बूढ़े तपस्वी को नहीं देना चाहते थे, और किसी ऋषि को नाराज़ भी नहीं करना चाहते थे। इसलिए उन्होंने ऐसा कन्या-मूल्य रखा जो उनके हिसाब से कोई तपस्वी कभी नहीं चुका सकता था: “मुझे एक हज़ार घोड़े लाकर दो, चाँदनी जैसे सफ़ेद, और हर एक का एक कान काला।” ऋचीक जल के स्वामी वरुण के पास गए, और वरुण ने उन्हें हज़ार घोड़े दे दिए। वे कान्यकुब्ज के पास गंगा से निकले, उस स्थान पर जिसे आज भी अश्वतीर्थ — घोड़ों का घाट — कहा जाता है। गाधि के पास कोई चारा नहीं बचा। सत्यवती ऋचीक की पत्नी बन गईं।",
 "c34de8d5": "एक काले कान वाले इन सफ़ेद घोड़ों को याद रखिए। कई वर्ष बाद ये फिर आएँगे, विश्वामित्र के शिष्य गालव की कथा में (अध्याय 11)।",
 "41cf740f": "दो कटोरे",
 "38b212e0": "ऋचीक अपनी पत्नी से प्रसन्न हुए और उन्हें वरदान माँगने को कहा। सत्यवती ने अपने लिए एक पुत्र माँगा — और अपनी माँ के लिए भी एक पुत्र, क्योंकि राजा गाधि के बाद राज करने वाला कोई पुत्र नहीं था। ऋचीक ने पवित्र चावल के दो कटोरे तैयार किए, जिन्हें चरु कहते हैं, हर एक में उनके मंत्रों की शक्ति भरी थी। “यह तुम्हारे लिए है,” उन्होंने सत्यवती से कहा। “तुम्हारा पुत्र एक महान ब्राह्मण होगा, शांत और ज्ञानी। यह तुम्हारी माँ के लिए है। उनका पुत्र एक महान क्षत्रिय होगा, एक शक्तिशाली राजा।”",
 "8fe384d8": "पर सत्यवती की माँ ने सोचा: “पति अपनी पत्नी के लिए ज़रूर बेहतर कटोरा बनाता होगा।” उन्होंने अपनी बेटी को कटोरे बदलने के लिए मना लिया, और दोनों स्त्रियों ने एक-दूसरे का चरु खा लिया। महाभारत का वन पर्व इसे थोड़ा अलग ढंग से कहता है: वहाँ ऋचीक के पिता, महर्षि भृगु, आशीर्वाद देते हैं, और स्त्रियों से दो पेड़ों को गले लगाने को भी कहा जाता है — माँ को पीपल (अश्वत्थ), बेटी को गूलर (उदुंबर)। वे पेड़ भी बदल लेती हैं।",
 "de28f078": "ऋचीक तुरंत समझ गए। “तुम्हारी माँ ने तुम्हें धोखा दिया है,” उन्होंने सत्यवती से कहा। “अब तुम्हारा पुत्र योद्धा के उग्र स्वभाव वाला ब्राह्मण होगा, और तुम्हारा भाई ब्राह्मण के हृदय वाला क्षत्रिय होगा।” सत्यवती उनके पैरों पर गिर पड़ीं। “कृपा कीजिए — मेरा पुत्र नहीं! यह मेरे पोते पर पड़े।” ऋचीक मान गए।",
 "9d2b10f4": "और ऐसा ही हुआ। सत्यवती के पुत्र सौम्य ऋषि {jamadagni|जमदग्नि} हुए। पर जमदग्नि के पुत्र {parashurama|परशुराम} हुए, वह ब्राह्मण जो फरसा धारण करते थे और जिन्होंने इक्कीस बार क्षत्रियों से युद्ध किया। और गाधि की रानी के यहाँ एक राजकुमार जन्मा जिसमें राजा का बल था — और उसके भीतर छिपी थी एक ऋषि की आत्मा। उसका नाम था विश्वामित्र।",
 "8bd9490c": "इस तरह विश्वामित्र और परशुराम एक ही परिवार के हैं: परशुराम की दादी सत्यवती विश्वामित्र की बहन थीं। दोनों में ब्राह्मण और क्षत्रिय का मेल है — हर एक में एक कटोरे का।",
 "57cf9e1f": "नाम, और एक बहन जो नदी बन गई",
 "7c7c27a6": "कुश के वंश के होने के कारण राजकुमार को कौशिक भी कहा जाता था, और गाधेय या गाधि-सुत, यानी “गाधि का पुत्र”। कुछ पुराण कहते हैं कि उनका पहला नाम विश्वरथ था। विश्वामित्र नाम का अर्थ है “सारे संसार का मित्र”।",
 "e015de1d": "उनकी बहन सत्यवती अपने पति से इतना प्रेम करती थीं कि जब ऋचीक ने यह संसार छोड़ा, तो वे अपने शरीर सहित उनके पीछे स्वर्ग चली गईं। फिर संसार के प्रति प्रेम के कारण वे नदी बनकर नीचे लौट आईं — पवित्र कौशिकी, जो हिमालय से बहती है। रामायण में विश्वामित्र राम से कहते हैं: “वह नदी मेरी बड़ी बहन है। उसके प्रति प्रेम के कारण मैं हिमालय पर, उसके किनारे रहता हूँ।”",
 "d7bbbb57": "कौशिकी आज की कोसी नदी है, जो नेपाल से उतरकर बिहार में बहती है।",
 "fb0f39ff": "कुश का परिवार और सौ राजकुमारियाँ: वाल्मीकि रामायण, बाल कांड, सर्ग 32–34। ऋचीक, घोड़े और दो कटोरे: महाभारत, वन पर्व और अनुशासन पर्व, तथा विष्णु और भागवत पुराण। कटोरे बदलने के ब्योरे में ग्रंथों में थोड़ा अंतर है।",
 "1ab451e9": "विश्वामित्र कुश के वंश के राजकुमार के रूप में जन्मे — कान्यकुब्ज के राजा {gadhi|गाधि} के पुत्र।",
 "68fa81ac": "दोनों कटोरे बदल जाने के कारण उनमें क्षत्रिय का बल था और भीतर ब्राह्मण की आत्मा।",
 "9537b155": "उनकी बहन सत्यवती कौशिकी नदी बन गईं; उनके पोते परशुराम थे।",
 "829d38bb": "कुशनाभ ने अपनी बेटियों की प्रशंसा की कि उन्होंने वायु को श्राप देने के बजाय क्षमा कर दिया। क्या यह प्रशंसा सही थी? क्षमा करने में क्या खोना पड़ता है, और उससे क्या मिलता है?",
 "4a6ef154": "राजा और कामधेनु गाय",
 "b927445a": "जब गाधि बूढ़े हुए, तो विश्वामित्र राजा बने। रामायण कहती है कि उन्होंने कई हज़ार वर्षों तक राज किया — बलवान, न्यायी और अपनी प्रजा के प्रति समर्पित। एक बार वे पूरी अक्षौहिणी — हाथियों, रथों, घोड़ों और पैदल सैनिकों की पूरी सेना — लेकर अपने राज्य में घूमने निकले। वे नगरों और राज्यों, नदियों, पर्वतों और वनों से होते हुए एक ऐसे स्थान पर पहुँचे जो सबसे अलग था: ऋषि {vasishtha|वसिष्ठ} का आश्रम।",
 "b7cd6a55": "आश्रम फूलों से लदे पेड़ों और लताओं से भरा था, जहाँ हिरण और पक्षी बेखटके घूमते थे। वहाँ ऐसे ऋषि रहते थे जो केवल जल, केवल वायु या केवल सूखे पत्ते खाकर रहते थे — उनमें से कुछ अग्नि की तरह चमकते थे। ब्रह्मा के पुत्र वसिष्ठ स्वयं जप में बैठे थे। विश्वामित्र ने हाथ जोड़कर उन्हें प्रणाम किया। वसिष्ठ ने उनका स्वागत किया, आसन दिया और फल-मूल भेंट किए। फिर दोनों ने एक-दूसरे का कुशल-क्षेम पूछा — राजा से उनके राज्य, खज़ाने, सेना और मित्रों के बारे में; ऋषि से उनकी तपस्या, उनके शिष्यों और उनकी पवित्र अग्नियों के बारे में।",
 "80a4f13d": "“अब मुझे आपको और आपकी पूरी सेना को भोजन कराने दीजिए,” वसिष्ठ ने कहा। विश्वामित्र मुस्कुराए। “आपने फल, जल और अपने मीठे वचनों से मेरा सम्मान कर ही दिया है। इतना काफ़ी है। वन में रहने वाला एक तपस्वी पूरी सेना को कैसे खिला सकता है?” पर वसिष्ठ बार-बार आग्रह करते रहे, जब तक राजा मान नहीं गए।",
 "94eb46cc": "वसिष्ठ ने खुशी से पुकारा: “आओ, शबला! जल्दी आओ!” एक चितकबरी गाय उनके पास आई — {shabala|शबला}, देवताओं की इच्छा पूरी करने वाली गाय कामधेनु की संतान। “मैं इस राजा और इनकी सेना को भोज कराना चाहता हूँ,” वसिष्ठ ने उससे कहा। “हमें हर प्रकार का भोजन दो — छहों रस, जो कुछ भी खाया, पिया, चाटा या चूसा जा सके।”",
 "b3a6a2e5": "और शबला ने दिया। चावल के पहाड़, मिठाइयों के ढेर, दूध, दही और घी की नदियाँ, गन्ना, शहद, हर तरह के पेय, चाँदी की थालियों में स्वादिष्ट पकवान। पूरी सेना ने तब तक खाया जब तक और खा न सकी — सैनिक खुश थे, और राजा चकित।",
 "46769a64": "तब विश्वामित्र के भीतर का राजा बोल उठा। “ऋषिवर, यह शबला मुझे दे दीजिए। इसके बदले मैं आपको एक लाख गायें दूँगा। ऐसा रत्न राजा का होता है — राज्य की हर कीमती चीज़ पर राजा का अधिकार है।”",
 "2adb9930": "“एक लाख गायों के बदले भी नहीं,” वसिष्ठ ने कहा, “न एक करोड़ के बदले, न चाँदी के ढेरों के बदले। सज्जन अपना अच्छा नाम नहीं छोड़ता, और मैं शबला को नहीं छोड़ूँगा। वह मेरा सब कुछ है। देवताओं और पितरों को मेरी आहुतियाँ उसी से आती हैं। मेरी पवित्र अग्नियाँ उसी के कारण जलती हैं। मेरे यज्ञों का स्वाहा और वषट्, मेरी सारी विद्या, इस आश्रम का जीवन — सब उसी पर टिका है। सच में, वह मेरा सब कुछ है।”",
 "8cae9ec5": "विश्वामित्र ने अपनी पेशकश बढ़ाई। “सोने के साज़ और अंकुश वाले चौदह हज़ार हाथी। आठ सौ सोने के रथ, हर एक में चार सफ़ेद घोड़े जुते और घंटियाँ लटकी हुईं। ग्यारह हज़ार उत्तम नस्ल के घोड़े। हर रंग की एक करोड़ गायें, जवान और स्वस्थ। सोना और रत्न — जितना आप चाहें। बस वह चितकबरी गाय मुझे दे दीजिए।” वसिष्ठ टस से मस नहीं हुए। “राजन, मैं उसे नहीं दूँगा। वह मेरा रत्न है, मेरा धन है, मेरा जीवन है।”",
 "9ed40f9c": "तब विश्वामित्र ने वही किया जो सेना वाला राजा कर सकता है। उन्होंने उसे ज़बरदस्ती ले लिया। उनके आदमियों ने शबला के गले में रस्सी बाँधी और उसे खींचकर ले जाने लगे।",
 "9a154b95": "“शबला, मैंने तुम्हें नहीं छोड़ा है,” वसिष्ठ ने दुखी होकर कहा। “तुमने मेरा कोई अपराध नहीं किया। यह राजा तुम्हें ज़बरदस्ती ले जा रहा है। वह बलवान है — एक क्षत्रिय, धरती का स्वामी, विशाल सेना वाला। उसके सामने मेरे पास क्या बल है?”",
 "7f11d5bd": "“ऐसा मत कहिए,” शबला ने कहा। “क्षत्रिय का बल सच्चा बल नहीं है। ब्राह्मण का बल बड़ा है — वह दिव्य है। आपकी शक्ति अपार है, और विश्वामित्र कितने भी बलवान हों, आपसे बढ़कर नहीं हैं। बस मुझे आज्ञा दीजिए। आपके ब्रह्मतेज से भरी मैं इस घमंडी राजा की सेना को कुचल दूँगी।” “तो एक सेना रचो,” वसिष्ठ ने कहा।",
 "db340860": "शबला ने हुंकार भरी, “हुं-भा!” — और उससे सैकड़ों पह्लव योद्धा निकले, जो विश्वामित्र की आँखों के सामने उनकी सेना का नाश करने लगे। क्रोधित राजा ने अपने अस्त्रों से उन्हें मार गिराया। तब उसने यवनों के साथ मिले शकों को रचा, जो सोने की तरह चमक रहे थे, तलवारों और भालों से लैस, और जो आग की तरह मैदान पर छा गए; राजा के अस्त्रों ने उन्हें भी काट डाला। तब उसने और योद्धा निकाले: उसके रँभाने से सूर्य जैसे तेजस्वी कांबोज; उसके थनों से हथियारबंद पह्लव; उसके पिछले भाग से यवन; उसके गोबर से शक; उसकी त्वचा के रोमछिद्रों से म्लेच्छ, हारीत और किरात। एक पल में इस विशाल सेना ने विश्वामित्र की पूरी सेना — पैदल, हाथी, घोड़े और रथ — नष्ट कर दी।",
 "72f0422c": "पह्लव, शक, यवन और कांबोज प्राचीन भारत के उत्तर-पश्चिम में रहने वाले वास्तविक लोग थे — मोटे तौर पर फ़ारसी, सीथियन, यूनानी और अफ़गान पहाड़ियों के लोग। यह कथा कल्पना करती है कि वे सब वसिष्ठ की गाय से जन्मे।",
 "6fc6f07e": "वाल्मीकि रामायण, बाल कांड, सर्ग 51–54, जो मिथिला में गौतम और अहल्या के पुत्र शतानंद ने राम को सुनाई। महाभारत (आदि पर्व, चैत्ररथ प्रसंग) यही कथा कहता है, जहाँ गाय का नाम नंदिनी है।",
 "64da84a2": "{vasishtha|वसिष्ठ} ने अपनी कामधेनु गाय {shabala|शबला} की सहायता से विश्वामित्र की पूरी सेना को भोजन कराया।",
 "4fa8ca20": "विश्वामित्र ने उसके बदले अपार धन देना चाहा और मना किए जाने पर उसे ज़बरदस्ती ले जाने की कोशिश की।",
 "fa14d70b": "शबला ने ऐसे योद्धा रचे जिन्होंने राजा की पूरी सेना नष्ट कर दी।",
 "f3145f12": "विश्वामित्र मानते थे कि उनके राज्य की हर कीमती चीज़ पर उनका अधिकार है। वसिष्ठ मानते थे कि कुछ चीज़ें किसी भी कीमत पर खरीदी नहीं जा सकतीं। आपके अपने जीवन में कौन-सी चीज़ें कभी बेची नहीं जा सकतीं?",
 "7e467c99": "अस्त्रों के सामने एक दंड",
 "da62fc06": "विश्वामित्र के सौ पुत्र थे। जब उन्होंने अपने पिता की सेना को नष्ट होते देखा, तो वे सब एक साथ हथियार उठाकर वसिष्ठ पर टूट पड़े। वसिष्ठ ने बस उनकी ओर देखा और एक ध्वनि की — “हुम्!” उसी क्षण सौ के सौ अपने घोड़ों और रथों समेत जलकर राख हो गए।",
 "821a9594": "विश्वामित्र मैदान में अकेले खड़े रह गए। रामायण उनका वर्णन ऐसे करती है जैसे लहरों के बिना सागर, टूटे दाँतों वाला साँप, ग्रहण लगा सूर्य — उनका सारा घमंड और तेज चला गया था। सेना मर चुकी थी, पुत्र मर चुके थे; उन्हें लगा जैसे वे बिना पंखों का पक्षी हों। उन्होंने अपने बचे हुए एक पुत्र को सिंहासन पर बिठाया, उससे धर्म से राज करने को कहा, और हिमालय चले गए।",
 "480a078d": "वहाँ उन्होंने {shiva|महादेव} की कठोर तपस्या की। जब शिव प्रकट हुए और वरदान माँगने को कहा, तो विश्वामित्र ने माँगा: “यदि आप मुझसे प्रसन्न हैं, तो मुझे धनुर्विद्या का पूरा ज्ञान उसके सारे रहस्यों सहित दीजिए — और देवताओं, दानवों, ऋषियों, गंधर्वों, यक्षों और राक्षसों को ज्ञात हर दिव्य अस्त्र।” “तथास्तु,” शिव ने कहा, और अपने धाम लौट गए।",
 "a4f73d57": "पूर्णिमा के सागर की तरह घमंड से फूले विश्वामित्र सीधे वसिष्ठ के आश्रम लौटे और अपने नए अस्त्रों से उसे जलाने लगे। वन में आग लग गई। ऋषि हर दिशा में भागे, हज़ारों हिरण और पक्षी डर के मारे भाग निकले, और पल भर में वह शांत आश्रम श्मशान की तरह सुनसान और खाली हो गया।",
 "527823c2": "वसिष्ठ ने अपने शिष्यों को पुकारा, “डरो मत! मैं गाधि के इस पुत्र को ऐसे नष्ट कर दूँगा जैसे सूर्य कोहरे को मिटा देता है।” उन्होंने अपना दंड उठाया — ब्रह्मदंड, लकड़ी का एक सादा दंड जिसमें उनकी तपस्या की शक्ति भरी थी — और मृत्यु के देवता यम की तरह विश्वामित्र के सामने खड़े हो गए। “वहीं रुक जा, दुष्ट क्षत्रिय,” उन्होंने कहा। “तूने युगों से खड़े आश्रम को नष्ट कर दिया है। दिखा तेरे पास क्या है।”",
 "6d304d84": "विश्वामित्र ने आग्नेय अस्त्र, अग्नि का अस्त्र, उठाकर छोड़ा। वसिष्ठ ने अपना दंड ऊपर किया और उसने आग को बस निगल लिया। तब विश्वामित्र ने एक के बाद एक वे सारे अस्त्र चलाए जो शिव ने उन्हें दिए थे: जल का वारुण, रुद्र का रौद्र, इंद्र का ऐंद्र, पाशुपत, ऐषीक; मानव, भ्रम में डालने वाला मोहन, गांधर्व, नींद लाने वाला स्वापन, जम्हाई दिलाने वाला जृंभण, मदहोश करने वाला मादन, झुलसाने वाला संतापन, रुलाने वाला विलापन, सुखा देने वाला शोषण, चीर देने वाला दारण।",
 "541844d0": "फिर वज्र, ब्रह्मा का पाश, काल का पाश और वरुण का पाश, शिव का अपना पिनाक, सूखा और गीला वज्र, दंड, पैशाच, क्रौंच, धर्मचक्र, कालचक्र, विष्णुचक्र, पवन का वायव्य, मथने वाला मथन, घोड़े के सिर वाला हयशिरस, दो बड़े भाले, कंकाल, मूसल गदा, विद्याधर, भयंकर कालास्त्र, त्रिशूल, कापाल और कंकण। दंड ने इन सबको ऐसे निगल लिया मानो वे कुछ थे ही नहीं।",
 "465518d7": "आखिर में विश्वामित्र ने ब्रह्मास्त्र उठाया, स्वयं ब्रह्मा का अस्त्र — सारे लोकों का सबसे भयानक अस्त्र। अग्नि के नेतृत्व में देवता, देवर्षि, गंधर्व और महानाग भयभीत हो गए; तीनों लोक काँप उठे। वसिष्ठ ने एक बार फिर अपना दंड ऊपर किया, और ब्रह्मास्त्र भी उसमें समा गया।",
 "4c0db8f8": "ब्रह्मास्त्र को निगलने के बाद वसिष्ठ ने भयंकर रूप धारण किया। उनके शरीर के हर रोमछिद्र से धुएँ के साथ लपटें निकलने लगीं, और उनके हाथ का दंड प्रलय की अग्नि की तरह धधकने लगा। ऋषि उनके पैरों पर गिर पड़े और विनती की: “हे ब्रह्मर्षि, आपकी शक्ति सिद्ध हो गई। अपने तेज को रोकिए! विश्वामित्र हार गए हैं। शांत हो जाइए, और लोकों को भय से मुक्त कीजिए।” और वसिष्ठ शांत हो गए।",
 "c11f2b28": "विश्वामित्र अपमानित, खाली हाथ, हाँफते हुए वहाँ खड़े रहे। तब उन्होंने वे शब्द कहे जिन्होंने उनका पूरा जीवन बदल दिया:",
 "ae6e33ca": "“धिक्कार है क्षत्रिय के बल को! ब्रह्मतेज का बल — वही सच्चा बल है। एक ब्रह्मदंड से मेरे सारे अस्त्र नष्ट हो गए।” (बाल 56.23)",
 "4794fcea": "“मैंने यह अपनी आँखों से देखा है,” उन्होंने कहा। “इसलिए मैं अपने मन और इंद्रियों को शुद्ध करूँगा, और ऐसी तपस्या करूँगा कि मैं भी ब्राह्मण बन जाऊँ।” वे घर नहीं गए। उन्होंने दूसरी सेना नहीं जुटाई। वे अपनी रानी के साथ दक्षिण की ओर मुड़ गए, अपने जीवन की सबसे लंबी लड़ाई शुरू करने — अपने आप से लड़ाई।",
 "2fc290c0": "वाल्मीकि रामायण, बाल कांड, सर्ग 55–56। अस्त्रों की सूची सर्ग 56 के अनुसार है।",
 "7945e4ad": "वसिष्ठ ने एक ध्वनि “हुम्!” से विश्वामित्र के सौ पुत्रों को भस्म कर दिया।",
 "9c0f3253": "विश्वामित्र ने शिव से हर दिव्य अस्त्र पाया — और वसिष्ठ के लकड़ी के दंड ने सबको निगल लिया, ब्रह्मास्त्र को भी।",
 "d05f2fdc": "“धिक्कार है क्षत्रिय बल को!” — विश्वामित्र ने तपस्या से ब्राह्मण बनने का निश्चय किया।",
 "18b611a8": "इस अध्याय में विश्वामित्र ने सब कुछ खो दिया। फिर भी इसी हार के कारण हम उन्हें एक महान ऋषि के रूप में याद करते हैं। क्या कभी-कभी हारना किसी बड़ी चीज़ की शुरुआत हो सकता है?",
 "9cb710a0": "राजर्षि — और त्रिशंकु का स्वर्ग",
 "a1b17434": "दक्षिण में विश्वामित्र और उनकी रानी फल-मूल खाकर रहे, और उन्होंने एक हज़ार वर्ष तक तपस्या की। वहाँ उनके चार पुत्र हुए — हविष्पंद, मधुष्पंद, दृढ़नेत्र और महारथ। हज़ार वर्ष पूरे होने पर {brahma|ब्रह्मा} उनके पास आए। “अपनी तपस्या से तुमने राजर्षियों के लोक जीत लिए हैं। तुम राजर्षि हो — राजा जो ऋषि हैं।”",
 "6f006d7c": "विश्वामित्र ने शर्म और क्रोध से सिर झुका लिया। “हज़ार वर्ष की तपस्या, और देवता अब भी मुझे ऐसा राजा कहते हैं जो संयोग से ऋषि है? तब तो मेरी तपस्या कुछ भी नहीं।” वे और भी कठोर तपस्या करने बैठ गए।",
 "55e17f84": "एक राजा जो शरीर सहित स्वर्ग चाहता था",
 "47b3e753": "उस समय अयोध्या के राजा इक्ष्वाकु वंश के {trishanku|त्रिशंकु} थे — सत्यवादी और संयमी। उनकी एक अजीब इच्छा थी: बिना मरे, अपने इसी शरीर के साथ स्वर्ग जाना। वे अपने कुलगुरु वसिष्ठ के पास गए। “यह नहीं हो सकता,” वसिष्ठ ने कहा।",
 "a3e96089": "तो त्रिशंकु दक्षिण में वसिष्ठ के सौ पुत्रों के पास गए, जो वहाँ तपस्या कर रहे थे। उन्होंने उन्हें प्रणाम किया और फिर वही माँगा। वे भड़क उठे। “हमारे पिता, तुम्हारे अपने गुरु, ने मना कर दिया है — और तुम उनकी पीठ पीछे हमारे पास आए हो? इक्ष्वाकु राजाओं ने हमेशा कुल-पुरोहित को सबसे बड़ा मार्गदर्शक माना है। उनकी कही बात पलटी नहीं जा सकती।” “तो मैं कोई दूसरा पुरोहित ढूँढ लूँगा,” त्रिशंकु ने कहा।",
 "117bcda4": "इस पर उन्होंने उन्हें श्राप दिया: “चांडाल हो जाओ!” अगली सुबह तक त्रिशंकु बदल चुके थे। उनकी त्वचा काली और खुरदरी हो गई थी, कपड़े गहरे नीले, बाल कटे हुए, गले में श्मशान की माला और लोहे के गहने। उनके मंत्रियों और प्रजा ने एक नज़र देखा और उन्हें छोड़ गए। अकेले, दिन-रात जलते हुए, वे उस एक व्यक्ति के पास गए जो शायद मदद कर सकता था: विश्वामित्र।",
 "84dcd612": "कथा सुनकर विश्वामित्र का मन दया से भर गया। और शायद कुछ और भी जागा — वह करने का मौका जिसे वसिष्ठ ने असंभव कहा था। “स्वागत है, इक्ष्वाकु पुत्र,” उन्होंने कहा। “मैं जानता हूँ तुम धर्मात्मा हो। डरो मत; मैं तुम्हें शरण दूँगा। मैं स्वयं तुम्हारे लिए यज्ञ करूँगा, और तुम इसी शरीर में स्वर्ग जाओगे — इसी चांडाल रूप में भी।”",
 "721ddf1b": "उन्होंने अपने पुत्रों को देश भर के हर ऋषि को निमंत्रण देने भेजा। उनके डर से सब आए — सिवाय वसिष्ठ के सौ पुत्रों और महोदय नाम के एक ऋषि के। उनका संदेश शब्दशः लौटाकर लाया गया: “जिस यज्ञ में पुरोहित क्षत्रिय हो और यजमान चांडाल, वहाँ देवता और ऋषि आहुति कैसे स्वीकार करेंगे? सिर्फ़ इसलिए कि विश्वामित्र उनकी रक्षा करते हैं, वे चांडाल का अन्न खाकर स्वर्ग कैसे जाएँगे?”",
 "4e484113": "विश्वामित्र की आँखें क्रोध से लाल हो गईं। “मैं तपस्या कर रहा हूँ और मैंने उनका कुछ नहीं बिगाड़ा, फिर भी वे मेरा अपमान करते हैं? वे जलकर राख हो जाएँ! सात सौ जन्मों तक वे कुत्ते का मांस खाने वाले मुष्टिक बनकर जन्में, कुरूप, धरती पर भटकते हुए। और महोदय — वह निषाद बनकर जन्मे, सबका घृणित, जीवों को मारने वाला।”",
 "3fbe2c69": "देखिए विश्वामित्र ने अभी क्या किया। उनकी तपस्या ने उन्हें बड़ी शक्ति दी थी — और उन्होंने उसे तुरंत एक श्राप में खर्च कर दिया। बाद में ब्रह्मा उन्हें बताएँगे कि ठीक इसी कारण वे अभी तक ब्रह्मर्षि नहीं हैं।",
 "4034745e": "यज्ञ शुरू हुआ। विश्वामित्र मुख्य पुरोहित थे। पर जब उन्होंने देवताओं को अपना भाग लेने बुलाया, तो एक भी देवता नहीं आया। तब विश्वामित्र का धैर्य टूट गया। उन्होंने क्रोध में यज्ञ की स्रुवा उठाई और त्रिशंकु से कहा: “मेरी अपनी तपस्या की शक्ति देखो। मैं अकेले अपनी शक्ति से तुम्हें शरीर सहित स्वर्ग भेजूँगा। जाओ!” और सारे ऋषियों की आँखों के सामने त्रिशंकु आकाश में उठ गए।",
 "6068392a": "वे स्वर्ग के द्वार तक पहुँचे। {indra|इंद्र} ने उन्हें देखा और कहा: “त्रिशंकु, लौट जाओ। यहाँ तुम्हारे लिए कोई जगह नहीं — तुम्हें तुम्हारे गुरु का श्राप है। सिर के बल धरती पर गिरो!” और त्रिशंकु उल्टे सिर नीचे गिरने लगे, चिल्लाते हुए: “विश्वामित्र, बचाइए! बचाइए!”",
 "cf5b2d82": "“रुको! वहीं ठहरो!” विश्वामित्र गरजे — और त्रिशंकु बीच आकाश में रुक गए। फिर क्रोध में विश्वामित्र एक दूसरा ब्रह्मांड रचने लगे। दक्षिणी आकाश में उन्होंने सात ऋषियों का एक नया समूह, नए सप्तर्षि, बनाया। उन्होंने नए नक्षत्र, नए तारे बनाए। फिर बोले, “मैं एक और इंद्र भी बनाऊँगा — या कोई इंद्र होगा ही नहीं,” और नए देवता रचने लगे।",
 "a336f9ee": "देवता, ऋषि और असुर घबराकर उनके पास दौड़े आए। “महात्मन, इस राजा को इसके गुरु का श्राप है। यह शरीर सहित स्वर्ग में प्रवेश नहीं कर सकता।” विश्वामित्र ने उत्तर दिया: “मैंने इसे वचन दिया है। मैं उसे झूठा नहीं कर सकता। त्रिशंकु शरीर सहित स्वर्ग में रहे — और मेरे बनाए ये तारे सदा रहें, जब तक लोक रहें।”",
 "f4a7016d": "देवता मान गए। “ऐसा ही हो। आपके तारे सूर्य के मार्ग से बाहर बने रहेंगे। और त्रिशंकु उनके बीच देवता की तरह चमकेंगे — जैसे हैं वैसे, उल्टे सिर।” इस तरह त्रिशंकु आकाश में उल्टे, अपने ही एक स्वर्ग में रह गए। आज भी जब कोई चीज़ बीच में अटक जाए — न इधर की, न उधर की — तो लोग कहते हैं कि वह “त्रिशंकु” की तरह लटकी है।",
 "2ec210da": "एक और कथा: विश्वामित्र त्रिशंकु के ऋणी क्यों थे",
 "72dc7561": "हरिवंश और पुराणों से",
 "cea2d450": "हरिवंश और कई पुराण एक अलग कथा कहते हैं। वहाँ त्रिशंकु का पहला नाम सत्यव्रत है। युवा राजकुमार के रूप में उन्होंने गलत काम किया और उनके पिता ने उन्हें निकाल दिया, और वसिष्ठ ने इसे नहीं रोका। उनके निर्वासन के दौरान बारह वर्ष का अकाल पड़ा। विश्वामित्र तपस्या के लिए दूर गए थे, और उनकी पत्नी और बच्चे भूखों मर रहे थे — इतना कि उन्होंने अपने मँझले बेटे के गले में रस्सी डाल दी, ताकि भोजन के बदले उसे बेच सकें। सत्यव्रत ने बालक को छुड़ाया और पूरे परिवार को खिलाया, हर दिन उनकी कुटिया के पास एक पेड़ पर हिरण का मांस टाँगकर। हरिवंश कहता है कि वह बालक आगे चलकर गालव कहलाया, गल यानी “गला” से।",
 "c51c2294": "एक दिन कोई शिकार न मिलने पर भूखे सत्यव्रत ने वसिष्ठ की गाय मारकर खा ली। वसिष्ठ ने उनका नाम त्रिशंकु रखा, “तीन दागों वाला” — पिता को नाराज़ करने के लिए, गुरु की गाय मारने के लिए, और विधि से अर्पित न किया गया मांस खाने के लिए। जब विश्वामित्र लौटे और जाना कि उनके परिवार को किसने जीवित रखा, तो वे बहुत कृतज्ञ हुए। उन्होंने त्रिशंकु को फिर से उनके पिता के सिंहासन पर बिठाया और, वसिष्ठ की इच्छा के विरुद्ध, उन्हें शरीर सहित स्वर्ग भेजा।",
 "6de6dfa4": "वाल्मीकि रामायण, बाल कांड, सर्ग 57–60। सत्यव्रत वाली कथा: हरिवंश (हरिवंश पर्व, अध्याय 12–13), ब्रह्म पुराण, देवी भागवत (स्कंध 7)।",
 "308bf19a": "हज़ार वर्ष की तपस्या के बाद ब्रह्मा ने विश्वामित्र को राजर्षि कहा — और वे संतुष्ट नहीं हुए।",
 "de5a8de0": "वसिष्ठ के पुत्रों ने {trishanku|त्रिशंकु} को चांडाल बनने का श्राप दिया; विश्वामित्र ने बदले में उन्हें श्राप दिया।",
 "ea31675c": "इंद्र ने त्रिशंकु को नीचे फेंका; विश्वामित्र ने उन्हें आकाश में रोक दिया और उनके चारों ओर नए तारे रच दिए।",
 "1a0dae35": "विश्वामित्र ने सारे देवताओं के विरुद्ध जाकर भी त्रिशंकु से किया वचन निभाया। पर उन्होंने क्रोध में सौ लोगों को श्राप भी दिया। क्या एक ही व्यक्ति एक ही दिन प्रशंसनीय भी और गलत भी हो सकता है?",
 "ff54f02f": "यज्ञ-स्तंभ पर शुनःशेप",
 "e361ffbe": "इस सारे क्रोध से दक्षिण उनकी तपस्या के लिए बिगड़ चुका था, इसलिए विश्वामित्र पश्चिम में पवित्र पुष्कर सरोवर गए और फल-मूल खाकर फिर से तपस्या शुरू की।",
 "1fcd3843": "उस समय अयोध्या के राजा {ambarisha|अंबरीष} एक महान यज्ञ कर रहे थे। पर {indra|इंद्र} ने बलि का पशु चुरा लिया। पुरोहित ने राजा से कहा: “राजन, यह अशुभ संकेत है — आपकी लापरवाही से पशु खो गया है, और लापरवाह राजा नष्ट हो जाता है। जल्दी पशु ढूँढिए, या उसकी जगह किसी मनुष्य को लाइए, इससे पहले कि अनुष्ठान विफल हो।”",
 "330e380b": "राजा ने नगरों, वनों और आश्रमों में खोज की, एक बालक के बदले हज़ारों गायें देने की पेशकश करते हुए। आखिर भृगुतुंग नाम के पर्वत पर उन्हें ऋषि {richika|ऋचीक} मिले — विश्वामित्र के बहनोई — जो अपनी पत्नी और तीन पुत्रों के साथ बैठे थे। अंबरीष ने प्रणाम करके कहा: “एक लाख गायों के बदले मुझे अपना एक पुत्र बेच दीजिए।”",
 "c2e8cadf": "दोपहर को राजा पुष्कर में आराम करने रुके। वहाँ शुनःशेप ने एक जाने-पहचाने व्यक्ति को देखा — अपने मामा विश्वामित्र, जो दूसरे ऋषियों के साथ तपस्या कर रहे थे। बालक दौड़कर उनकी गोद में जा गिरा, रोते हुए, प्यास और डर से उसका मुँह सूखा हुआ। “मेरी न माँ बची, न पिता, न कोई रिश्तेदार, न कोई मित्र। मामा, मुझे बचाइए! आप सबके आश्रय हैं। राजा का यज्ञ भी पूरा हो जाए, और मैं भी जीवित रहूँ — मैं तपस्या करूँ और स्वर्ग पाऊँ।”",
 "b063d392": "विश्वामित्र ने बालक को ढाढ़स बँधाया और अपने पुत्रों की ओर मुड़े। “पिता परलोक के भले के लिए पुत्र पाते हैं, और यह वही समय है। यह बालक एक ऋषि का पुत्र है और मेरी शरण में आया है। तुममें से किसी एक को राजा के साथ जाकर इसकी जगह यज्ञ-पशु बनना होगा। तब राजा का अनुष्ठान पूरा होगा, देवता तृप्त होंगे, और मेरा वचन भी रहेगा।”",
 "192b41a6": "उनका पुत्र मधुष्पंद और दूसरे हँस पड़े। “किसी और के बेटे को बचाने के लिए आप अपने ही बेटों की बलि कैसे दे सकते हैं? यह तो कुत्ते का मांस खाने जितना गलत है।” विश्वामित्र की आँखें जल उठीं। “तुम धर्म का उल्लंघन करके, बेशर्मी से, मुझसे इस तरह बात करने की हिम्मत करते हो? तो तुम भी वसिष्ठ के पुत्रों जैसे होगे — मुष्टिक बनकर जन्मोगे, कुत्ते का मांस खाओगे, हज़ार वर्ष तक धरती पर भटकोगे!”",
 "1822535f": "यह दूसरी बार है जब विश्वामित्र ने क्रोध में लोगों को श्राप दिया — और इस बार अपने ही पुत्रों को।",
 "7197ae5f": "तब विश्वामित्र ने शुनःशेप को दो गुप्त स्तुतियाँ दीं। “जब तुम्हें लाल फूलों और लाल चंदन के साथ यज्ञ-स्तंभ से बाँधा जाए, और तुम अग्नि के सामने खड़े हो, तब ये दो स्तुतियाँ गाना — एक इंद्र की, और एक इंद्र के छोटे भाई उपेंद्र (विष्णु) की। तब तुम्हें जो चाहिए वह मिलेगा।”",
 "b2a05f87": "शुनःशेप ने उन्हें कंठस्थ कर लिया। वह राजा के साथ यज्ञ में गया, लाल वस्त्रों में स्तंभ से बाँधा गया, और वहाँ — मृत्यु के सामने — उसने पूरे हृदय से इंद्र और उपेंद्र की स्तुति गाई। इंद्र प्रसन्न हुए। वे यज्ञ में आए, बालक को मुक्त किया और उसे लंबी आयु दी। और इंद्र की कृपा से राजा अंबरीष को भी अपने यज्ञ का पूरा फल मिला।",
 "633c8b8f": "विश्वामित्र, अपनी ओर से, एक और हज़ार वर्ष के लिए पुष्कर में अपनी तपस्या में लौट गए।",
 "0ce0ebdb": "सबसे पुरानी कथा: ऐतरेय ब्राह्मण",
 "ee0866a1": "यह कथा रामायण से बहुत पुरानी है। ऋग्वेद का ऐतरेय ब्राह्मण इसे ऐसे कहता है। इक्ष्वाकु वंश के राजा {harishchandra|हरिश्चंद्र} का कोई पुत्र नहीं था। उन्होंने वरुण से प्रार्थना की और वचन दिया: “यदि मेरे पुत्र हुआ, तो मैं उसे आपको अर्पित कर दूँगा।” पुत्र रोहित पैदा हुआ। पर हरिश्चंद्र बहाने बनाते रहे — “जब वह दस दिन का हो जाए,” “जब उसके दाँत आ जाएँ,” “जब उसके दाँत गिर जाएँ,” “जब वह कवच पहन सके।” जब रोहित बड़ा हुआ और उसने वचन के बारे में सुना, तो वह अपना धनुष लेकर वन में भाग गया।",
 "6898b3b7": "वरुण ने हरिश्चंद्र को ऐसा रोग दिया जिससे उनका पेट पानी से फूल गया। छह वर्ष तक रोहित भटकता रहा, और हर वर्ष इंद्र मनुष्य रूप में उससे मिलकर कहते, “चलते रहो — चरैवेति! बैठे रहने वाले का भाग्य बैठा रहता है; चलने वाले का भाग्य चलता है।” छठे वर्ष रोहित को एक भूखा ब्राह्मण अजीगर्त मिला, जिसके तीन पुत्र थे, और उसने मँझले पुत्र — शुनःशेप — को सौ गायों में खरीद लिया, ताकि अपनी जगह उसकी बलि दी जाए।",
 "9fcb78bd": "यज्ञ में विश्वामित्र होता पुरोहित थे। पर कोई भी बालक को स्तंभ से बाँधने को तैयार नहीं था। उसके अपने पिता अजीगर्त ने कहा, “मुझे सौ गायें और दो तो मैं करूँगा” — और उसने किया। फिर कोई उसे मारने को तैयार नहीं था। फिर से पिता ने कहा, “सौ गायें और,” और छुरी तेज़ करता हुआ आगे आया। यह देखकर शुनःशेप ने सोचा, “ये मुझे ऐसे मारेंगे जैसे मैं मनुष्य ही नहीं। मैं देवताओं की शरण लूँगा।” उसने एक के बाद एक स्तुतियाँ गाईं — प्रजापति, अग्नि, सविता, वरुण, विश्वेदेव, इंद्र, अश्विनीकुमार और उषा, यानी भोर की। हर मंत्र के साथ उसका एक बंधन ढीला होकर गिरता, और हरिश्चंद्र का फूला पेट छोटा होता जाता। अंतिम मंत्र के साथ वह मुक्त हो गया, और राजा स्वस्थ हो गए।",
 "c6306fef": "तब अजीगर्त अपने पुत्र को वापस चाहता था। शुनःशेप ने मना कर दिया: “आपने मुझ पर छुरी उठाई, जो कोई शूद्र भी नहीं करता। आपने मेरी जगह तीन सौ गायें चुनीं।” विश्वामित्र खड़े हुए और बोले, “यह अब तुम्हारा नहीं है। यह मेरा है।” उन्होंने शुनःशेप को अपना सबसे बड़ा पुत्र बनाकर गोद ले लिया, और उसे नया नाम दिया: देवरात, “देवताओं का दिया हुआ”।",
 "f6963fd7": "विश्वामित्र के एक सौ एक पुत्र थे। उनमें से पचास उनके पुत्र मधुच्छंदा से बड़े थे, और उन्होंने इस बाहरी व्यक्ति को अपना बड़ा भाई मानने से इनकार कर दिया। विश्वामित्र ने उन्हें श्राप दिया: “तुम्हारे वंशज देश की सीमाओं पर रहेंगे।” ब्राह्मण ग्रंथ कहता है कि उन्हीं से आंध्र, पुंड्र, शबर, पुलिंद और मूतिब आए। पर मधुच्छंदा और पचास छोटे पुत्रों ने कहा, “पिताजी जो भी तय करें, हमें स्वीकार है। हम देवरात को अपना बड़ा मानते हैं।” विश्वामित्र ने उन्हें आशीर्वाद दिया: “तुम्हें पुत्र और पशुधन मिलेंगे, क्योंकि तुमने मुझे पुत्रों वाला पिता बनाया है।”",
 "a5c02d86": "शुनःशेप की गाई स्तुतियाँ आज भी ऋग्वेद में हैं — मंडल 1, सूक्त 24 से 30। और आज्ञा मानने वाला पुत्र मधुच्छंदा स्वयं एक वैदिक ऋषि है: ऋग्वेद के बिल्कुल पहले सूक्त, जो “अग्निमीळे पुरोहितम्” से शुरू होते हैं, उन्हीं के हैं।",
 "f7589af2": "हाँ — संस्कृत साहित्य में कहीं भी आंध्रों का यह सबसे पहला उल्लेख है। यह उन्हें उस समय वैदिक प्रदेशों की सीमाओं के पार रहने वाले लोगों में गिनाता है।",
 "588ec11a": "वाल्मीकि रामायण, बाल कांड, सर्ग 61–62। ऐतरेय ब्राह्मण 7.13–18 (शुनःशेप आख्यान, जो राजसूय में सुनाया जाता है)। ऋग्वेद 1.24–30। राजा, पिता और श्राप के बारे में रामायण और ब्राह्मण ग्रंथ में अंतर है; यहाँ दोनों दिए गए हैं।",
 "e3a2d858": "{shunahshepa|शुनःशेप} को बलि के लिए बेचा गया और वह शरण के लिए विश्वामित्र के पास भागा।",
 "516f48ee": "विश्वामित्र ने उसे स्तुतियाँ सिखाईं; स्तंभ पर देवताओं की स्तुति करने से बालक मुक्त हो गया।",
 "00cf6201": "विश्वामित्र ने उसे देवरात के रूप में गोद लिया — और उसे न मानने वाले पुत्रों को श्राप दिया।",
 "329d4804": "विश्वामित्र ने अपने ही पुत्रों से कहा कि वे मदद माँगने आए एक बालक के लिए जान दें। क्या वे महान थे, या अपने पुत्रों के साथ अन्याय कर रहे थे? क्या कोई और रास्ता हो सकता था?",
 "8aef0185": "मेनका, और शकुंतला का जन्म",
 "80cc9610": "जब पुष्कर में हज़ार वर्ष पूरे हुए, तो विश्वामित्र ने स्नान किया, और देवता ब्रह्मा के साथ उन्हें पुरस्कार देने आए। “अब तुम ऋषि हो,” ब्रह्मा ने कहा। यह पहले से एक सीढ़ी ऊपर था। विश्वामित्र ने प्रणाम किया — और सीधे फिर तपस्या में लौट गए।",
 "06097f9b": "उनकी तपस्या इतनी उग्र हो गई कि {indra|इंद्र} डर गए। महाभारत बताता है कि इंद्र ने क्या सोचा: तपस्या से जलता यह राजा से बना ऋषि एक दिन इंद्र का अपना सिंहासन ले सकता है। इसलिए इंद्र ने अप्सराओं में सबसे सुंदर {menaka|मेनका} को बुलाया और कहा: “विश्वामित्र के पास जाओ। उन्हें लुभाओ। उनकी तपस्या भंग करो।”",
 "bff92a59": "मेनका डर गई। “प्रभु, आप स्वयं इस व्यक्ति से डरते हैं — और मुझे भेज रहे हैं? उनका क्रोध भयानक है। उन्होंने वसिष्ठ को हिला दिया। उन्होंने त्रिशंकु के लिए तारों से भरा नया स्वर्ग बना दिया। जो व्यक्ति ऐसा कर सकता है, वह एक नज़र से मुझे भस्म कर सकता है। यदि मुझे जाना ही है, तो पवन देवता मेरे साथ चलें ताकि मेरा वस्त्र उड़ा सकें, और प्रेम के देवता कामदेव मेरी सहायता करें।” इंद्र मान गए।",
 "4e750097": "मेनका पुष्कर आई और उस सरोवर में स्नान करने लगी जिसके पास विश्वामित्र बैठे थे। रामायण कहती है कि उसकी सुंदरता बादल में बिजली की तरह चमकी। जैसे ही वह जल से बाहर निकली, हवा ने उसका वस्त्र उड़ा दिया। विश्वामित्र ने आँखें खोलीं और उसे देखा — और जो ऋषि वसिष्ठ के दंड के सामने बिना डरे खड़े रहे थे, वे काम के वश में हो गए।",
 "c972c401": "“स्वागत है, अप्सरा,” उन्होंने कहा। “यहीं मेरे आश्रम में रहो। मुझसे प्रेम करो — मैं तुम्हारे प्रेम में खो गया हूँ।” वह रुक गई। वे पति-पत्नी की तरह साथ रहे, और रामायण कहती है कि पूरे दस वर्ष एक दिन-रात की तरह, खुशी-खुशी बीत गए, और उनकी तपस्या भुला दी गई।",
 "38519abe": "फिर एक दिन विश्वामित्र मानो सपने से जागे। वे शर्म और दुख से भर गए। “यह देवताओं का काम था,” वे समझ गए। “उन्होंने मेरी तपस्या चुराने के लिए उसे भेजा। दस वर्ष — इच्छा और सुख में एक रात की तरह चले गए। मेरी तपस्या की हर बाधा उन्हीं से आई है।” उन्होंने लंबी, गहरी साँस ली।",
 "85f1d179": "मेनका हाथ जोड़े, काँपती हुई उनके सामने खड़ी थी, उसे पक्का यकीन था कि वे उसे श्राप देंगे। पर इस बार विश्वामित्र ने श्राप नहीं दिया। उन्होंने उससे कोमलता से बात की और उसे जाने दिया। फिर वे पुष्कर छोड़कर उत्तर में हिमालय की ओर चल पड़े, कौशिकी के किनारे — वह नदी जो उनकी बहन {satyavati|सत्यवती} थी। वहाँ काम को जीतने का दृढ़ संकल्प लेकर उन्होंने फिर से तपस्या शुरू की।",
 "8723f8e6": "बदलाव देखिए। वसिष्ठ के पुत्रों और अपने पुत्रों के साथ क्रोध जीत गया और उन्होंने श्राप दिया। मेनका के साथ, जिसने सच में उनकी तपस्या भंग की थी, उन्होंने श्राप नहीं दिया। वे सीख रहे हैं।",
 "0cdb5722": "वह छोटी बच्ची जिसकी पक्षियों ने रक्षा की",
 "d244aa3b": "रामायण यहीं रुक जाती है, पर महाभारत बताता है कि उन दस वर्षों का क्या फल हुआ। मेनका के गर्भ में विश्वामित्र की संतान थी। हिमालय की एक ढलान पर, मालिनी नदी के किनारे, उसने एक बच्ची को जन्म दिया। फिर संसार में अपना काम पूरा करके वह नवजात को नदी किनारे छोड़कर इंद्र के स्वर्ग लौट गई।",
 "6736809e": "बच्ची शेरों और बाघों से भरे वन में अकेली पड़ी थी। पर पक्षियों का एक झुंड — शकुंत — उसके चारों ओर इकट्ठा हो गया और जंगली जानवरों से उसकी रक्षा करने लगा। ऋषि {kanva|कण्व} नदी में स्नान करने आए, पक्षियों से घिरी बच्ची को देखा, और उसे अपने आश्रम ले गए। क्योंकि शकुंतों ने उसकी रक्षा की थी, उन्होंने उसका नाम {shakuntala|शकुंतला} रखा, और उसे अपनी बेटी की तरह पाला।",
 "a1c73b68": "वर्षों बाद राजा दुष्यंत शिकार करते हुए कण्व के आश्रम आए और शकुंतला से मिले। उसने उन्हें अपने जन्म की पूरी कथा सुनाई — विश्वामित्र, मेनका, पक्षी और कण्व। उन्होंने गांधर्व विधि से विवाह किया, और उनके पुत्र भरत हुए — वह महान सम्राट जिनके नाम पर हमारे देश का नाम भारत पड़ा।",
 "4726a5ed": "तो हमारे देश का नाम विश्वामित्र के नाती से आया है। बाद में कालिदास ने इस कथा को अपने प्रसिद्ध नाटक अभिज्ञानशाकुंतलम् में ढाला।",
 "a151ccd5": "महर्षि",
 "b9eba591": "कौशिकी के किनारे विश्वामित्र ने एक और हज़ार वर्ष तपस्या की। अंत में देवता ब्रह्मा के पास गए, और ब्रह्मा मीठे वचनों के साथ उनके पास आए: “स्वागत है, महान ऋषि। मैं तुम्हारी तपस्या से प्रसन्न हूँ। मैं तुम्हें महर्षि की उपाधि देता हूँ — महान ऋषि — और ऋषियों में पहला स्थान।”",
 "6c497027": "विश्वामित्र न खुश हुए, न दुखी। उन्होंने हाथ जोड़कर पूछा: “यदि मैंने अपने कर्मों से महर्षि की उपाधि पाई है — तो क्या मैं ब्रह्मर्षि हूँ? क्या मैंने अपनी इंद्रियों को जीत लिया है?” ब्रह्मा ने सच-सच उत्तर दिया: “अभी नहीं। तुमने अभी अपनी इंद्रियों को नहीं जीता है। प्रयास करते रहो, ऋषियों में सिंह।” और वे चले गए।",
 "fd56e075": "तो विश्वामित्र खड़े हो गए — सचमुच। वे अपनी भुजाएँ ऊपर उठाए, बिना किसी सहारे के, केवल वायु पर जीते हुए खड़े रहे। गर्मियों में वे पंचाग्नि के बीच बैठते — चार अग्नियाँ चारों ओर और ऊपर सूर्य। वर्षा ऋतु में वे खुले आकाश के नीचे खड़े रहते। सर्दियों में दिन-रात पानी में खड़े रहते। उन्होंने ऐसा और एक हज़ार वर्ष किया।",
 "e3d51bbd": "वाल्मीकि रामायण, बाल कांड, सर्ग 63। महाभारत, आदि पर्व (संभव पर्व), क्रिटिकल एडिशन में अध्याय 65–66, जहाँ शकुंतला दुष्यंत को अपने जन्म के बारे में बताती है।",
 "a7c776f9": "इंद्र ने {menaka|मेनका} को भेजा; विश्वामित्र दस वर्ष उसके साथ रहे, तपस्या भूलकर।",
 "549e34e9": "उनकी बेटी {shakuntala|शकुंतला} थी, जिसकी पक्षियों ने रक्षा की और कण्व ने पाला — भरत की माँ।",
 "0c84cd39": "ब्रह्मा ने उन्हें महर्षि बनाया, पर कहा कि उन्होंने अभी इंद्रियों को नहीं जीता है।",
 "edc0791a": "ब्रह्मा विश्वामित्र की चापलूसी कर सकते थे। इसके बजाय उन्होंने साफ़ सच कहा: “अभी नहीं।” जब कोई सच सुनना न चाहे, तब उसे सच बताना क्या दया है?",
 "3cbaee58": "रंभा, मौन, और ब्रह्मर्षि",
 "616f6cc9": "एक बार फिर विश्वामित्र की तपस्या से देवता डर गए। इस बार {indra|इंद्र} ने अप्सरा {rambha|रंभा} को बुलाया। “रंभा, तुम्हें देवताओं के लिए यह करना होगा। जाओ, विश्वामित्र को मोहित करो, और उन्हें काम में डुबो दो।”",
 "0cdae2b2": "रंभा ने काँपते हुए हाथ जोड़े। “देवराज, यह ऋषि भयानक हैं। वे ज़रूर अपना क्रोध मुझ पर उतारेंगे। कृपया — मुझसे यह मत करवाइए।” पर इंद्र ने कहा, “डरो मत। मैं कोयल बनकर पेड़ों पर गाता हुआ तुम्हारे साथ रहूँगा, और {kama|कामदेव} भी आएँगे, और वसंत होगा। अपना सबसे सुंदर रूप धरो और उनकी तपस्या भंग करो।”",
 "7f65dbb8": "तो रंभा मुस्कुराती, मनोहर रूप में आई। पेड़ों पर फूल खिल उठे, और पास में एक कोयल मीठा गाने लगी। विश्वामित्र ने कोयल सुनी, आँखें खोलीं, और रंभा को देखा — और पल भर के लिए उनका मन डोल गया। पर इस बार वे तुरंत समझ गए। “यह फिर से इंद्र का काम है।” और उनके भीतर क्रोध उठा।",
 "f2f2e81e": "“रंभा,” उन्होंने कहा, “तुम मुझे लुभाने आई, जबकि मैं काम और क्रोध को जीतने का प्रयास कर रहा हूँ। इसके लिए तुम दस हज़ार वर्ष पत्थर बनकर खड़ी रहोगी। फिर महान तपस्या वाला एक ब्राह्मण तुम्हें मुक्त करेगा।” रंभा पत्थर बन गई। कामदेव और कोयल भाग गए।",
 "340acc0a": "रामायण उस ब्राह्मण का नाम नहीं बताती जिसने रंभा को मुक्त किया। बाद की कथाएँ कहती हैं कि वे स्वयं वसिष्ठ थे।",
 "e17548f6": "जैसे ही श्राप उनके होंठों से निकला, विश्वामित्र जान गए कि वे फिर हार गए। वे काम से नहीं गिरे थे — पर क्रोध से गिर गए थे, और श्राप ने उनकी इकट्ठा की हुई सारी तपस्या जला दी थी। वे दुखी होकर बैठे और एक व्रत लिया:",
 "432f9475": "“अब से मैं कभी क्रोध नहीं करूँगा, और एक शब्द नहीं बोलूँगा। मैं साँस नहीं लूँगा, और अपने शरीर को सुखा दूँगा, ज़रूरत पड़े तो हज़ार वर्ष तक, जब तक मैं सच में ब्राह्मण न बन जाऊँ। चाहे मेरा शरीर सूखकर नष्ट हो जाए, कोई मुझे यह तपस्या तोड़ते नहीं देखेगा।”",
 "7de039d7": "वे हिमालय छोड़कर पूर्व की ओर गए। वहाँ उन्होंने पूर्ण मौन का व्रत लिया और हज़ार वर्ष तक लकड़ी के लट्ठे की तरह खड़े रहे। कई बाधाएँ आईं; किसी ने उन्हें नहीं डिगाया। क्रोध उनके हृदय में नहीं घुसा।",
 "e7a1799b": "जब हज़ार वर्ष पूरे हुए, तो वे अपना उपवास तोड़ने की तैयारी करने लगे। जैसे ही वे खाने बैठे, इंद्र एक भूखे ब्राह्मण के वेश में आए और भोजन माँगा। विश्वामित्र ने उन्हें सारा भोजन दे दिया — हर दाना — बिना एक शब्द बोले, क्योंकि वे अब भी मौन व्रत में थे। उन्होंने कुछ नहीं खाया। उन्होंने शिकायत नहीं की। उन्होंने यह पूछने के लिए भी मुँह नहीं खोला कि वह व्यक्ति कौन है।",
 "dc150b29": "फिर उन्होंने अपनी साँस रोक ली — और एक और हज़ार वर्ष रोके रखी। उनके सिर के ऊपर से धुआँ उठने लगा। तीनों लोक तपने लगे और भयभीत हो गए। सागर उफनने लगे, पर्वत फट गए, धरती काँपने लगी, सूर्य की रोशनी चली गई, और हवाएँ बहना बंद हो गईं।",
 "c9a669ff": "देवता दौड़कर ब्रह्मा के पास गए। “हमने उन्हें बार-बार लुभाया और क्रोधित किया, फिर भी उनकी तपस्या बढ़ती जा रही है। उनमें ज़रा-सा भी दोष नहीं बचा। यदि उन्हें उनकी इच्छित वस्तु नहीं दी गई, तो उनकी तपस्या तीनों लोकों को नष्ट कर देगी। कृपया — इससे पहले कि वे सब कुछ जला देने का निश्चय करें, उन्हें वह दे दीजिए।”",
 "626be00b": "तब {brahma|ब्रह्मा} और सारे देवता विश्वामित्र के पास आए। “स्वागत है, ब्रह्मर्षि! हम तुम्हारी तपस्या से प्रसन्न हैं। अपनी उग्र तपस्या से तुम ब्राह्मण बन गए हो। मैं तुम्हें लंबी आयु देता हूँ। तुम्हारा सब मंगल हो। जहाँ चाहो जाओ।”",
 "a3a1c7d5": "विश्वामित्र ने प्रणाम किया, आखिरकार प्रसन्न होकर। पर उन्होंने दो चीज़ें और माँगीं। “यदि मैं सच में ब्रह्मर्षि हूँ, तो ओंकार, वषट्कार और वेद मेरे पास आएँ। और ब्रह्मा के पुत्र, वेदों के सबसे बड़े ज्ञाता वसिष्ठ स्वयं मुझे ब्रह्मर्षि कहें। तब मैं संतुष्ट होऊँगा, और तब आप जा सकते हैं।”",
 "6690ad89": "देवता {vasishtha|वसिष्ठ} के पास गए और उनसे विनती की। और वसिष्ठ आए। सब कुछ होने के बाद — चुराई गई गाय, जलाया गया आश्रम, अस्त्र, उनके पुत्रों पर श्राप — वे आए, और सब देवताओं के सामने सीधे कहा: “तुम ब्रह्मर्षि हो। इसमें कोई संदेह नहीं।” और उन्होंने विश्वामित्र को मित्र की तरह गले लगा लिया।",
 "f96784b0": "अब ब्रह्मर्षि बने विश्वामित्र ने बदले में वसिष्ठ को ऋषियों में श्रेष्ठ मानकर सम्मान दिया। देवता अपने घर लौट गए। और विश्वामित्र सारे संसार के मित्र बनकर धरती पर विचरने लगे, जैसा उनका नाम हमेशा कहता आया था।",
 "1d286b2a": "मिथिला में राम को यह कथा सुना रहे शतानंद इसे ऐसे समाप्त करते हैं: “राम, ये हैं विश्वामित्र — ऋषियों में सबसे महान, मनुष्य रूप में तपस्या, धर्म और बल का घर। तुम धन्य हो कि ये तुम्हारे मार्गदर्शक हैं।”",
 "e4769143": "सीढ़ियाँ गिनिए: राजा → राजर्षि → ऋषि → महर्षि → ब्रह्मर्षि। हर सीढ़ी में हज़ार वर्ष या उससे अधिक लगे — और हर बार गिरना काम या क्रोध के कारण हुआ।",
 "63c116e6": "वाल्मीकि रामायण, बाल कांड, सर्ग 64–65।",
 "91af4c82": "वे {rambha|रंभा} से मोहित नहीं हुए — पर उन्होंने उसे पत्थर बनने का श्राप दिया, और क्रोध के कारण अपनी तपस्या खो दी।",
 "f507367d": "उन्होंने हज़ार वर्ष मौन रखा, अपना एकमात्र भोजन दे दिया, और तब तक साँस रोके रखी जब तक उनके सिर से धुआँ नहीं उठने लगा।",
 "6eaf8d18": "ब्रह्मा ने उन्हें ब्रह्मर्षि बनाया, और स्वयं वसिष्ठ ने उन्हें ब्रह्मर्षि मानकर गले लगाया।",
 "bc22e1d2": "विश्वामित्र सेनाओं को हरा सकते थे, पर क्रोध उन्हें बार-बार हरा देता था। इसका क्या अर्थ है कि सबसे कठिन शत्रु उनके भीतर था?",
 "3e909b51": "जब सरस्वती लाल बही",
 "4c8a0eee": "रामायण वसिष्ठ और विश्वामित्र के झगड़े को एक आलिंगन के साथ समाप्त करती है। पर महाभारत और पुराण उनके बीच और लड़ाइयाँ याद रखते हैं — और वे यह नहीं छिपाते कि यह होड़ कितनी कड़वी हो गई थी। वे हमेशा ठीक-ठीक नहीं बताते कि ये बातें कब हुईं। हम उन्हें यहाँ वैसे ही सुनाते हैं जैसे वे कही जाती हैं।",
 "967aaab9": "महाभारत यह कथा तब सुनाता है जब कृष्ण के बड़े भाई बलराम {sarasvati|सरस्वती} नदी के किनारे-किनारे तीर्थयात्रा पर जाते हैं और वसिष्ठापवाह नाम के एक पवित्र स्थान पर रुकते हैं — “वह स्थान जहाँ वसिष्ठ बहा ले जाए गए”। इसका यह नाम ऐसे पड़ा।",
 "684be134": "वसिष्ठ और विश्वामित्र दोनों के आश्रम सरस्वती के किनारे, स्थाणु (शिव) के मंदिर के पास थे। वे तपस्या में प्रतिद्वंद्वी थे, और विश्वामित्र यह सहन नहीं कर पाते थे कि वसिष्ठ की तपस्या कितनी महान है। दिन-रात वे बस एक ही बात सोचते: उन्हें कैसे नीचा दिखाया जाए।",
 "ff7fdc5f": "एक दिन विश्वामित्र ने नदी देवी सरस्वती को अपने पास बुलाया। वह अपने रूप में, सुंदर, हाथ जोड़े आईं। “अपनी धारा से वसिष्ठ को जल्दी मेरे पास ले आओ,” उन्होंने आदेश दिया। “आज मैं उन्हें मार डालूँगा।”",
 "06d3ccd7": "सरस्वती का रंग उड़ गया और वे हवा में बेल की तरह काँपने लगीं। वे दोनों ऋषियों से डरी हुई थीं — मना करने पर विश्वामित्र के श्राप से, और मानने पर वसिष्ठ को मरवाने में सहायता के पाप से। वे वसिष्ठ के पास गईं और रोते हुए उन्हें सब बता दिया।",
 "78cf335c": "वसिष्ठ ने देखा कि वे कितनी डरी हुई हैं। “नदियों में श्रेष्ठ, अपने आप को बचाओ,” उन्होंने कोमलता से कहा। “अपनी तेज़ धारा से मुझे विश्वामित्र के पास ले चलो। उन्हें तुम्हें श्राप मत देने दो।” ऐसी थी उनकी शांति — वे नदी को दुख देने के बजाय अपनी मृत्यु की ओर जाना पसंद करते।",
 "29ba171a": "तो सरस्वती उफनीं और उसी किनारे को काट दिया जिस पर वसिष्ठ जप कर रहे थे, और उन्हें किनारे समेत बहाकर नीचे विश्वामित्र के पास ले गईं। अपने प्रतिद्वंद्वी को आते देख विश्वामित्र उन्हें मारने के लिए उत्सुकता से कोई हथियार ढूँढने लगे।",
 "c791d0fc": "तब सरस्वती ने एक साहसी काम किया। ब्राह्मण की मृत्यु के पाप से डरकर उन्होंने अपनी धारा मोड़ी और वसिष्ठ को तेज़ी से वापस पूर्व की ओर, विश्वामित्र की पहुँच से बाहर बहा ले गईं। उन्होंने उनका आदेश भी माना था — और वसिष्ठ को भी बचा लिया था।",
 "d6cc59e7": "विश्वामित्र के क्रोध की कोई सीमा न रही। “नदी, तुम मुझे धोखा देकर उन्हें बहा ले गईं, तो अब खून बनकर बहो! तुम्हारे जल में खून मिला हो, जो राक्षसों को प्रिय हो।” और पूरे एक वर्ष पवित्र सरस्वती लाल बहती रही। राक्षस झुंड के झुंड उसका जल पीने आते और उसके किनारों पर मज़े से रहते।",
 "798a0044": "एक वर्ष बाद कुछ ऋषि तीर्थयात्रा पर आए और पवित्र नदी को खून के साथ बहते देखा। वे स्तब्ध रह गए। “यह क्या है?” काँपती हुई सरस्वती ने उन्हें पूरी कथा सुनाई। ऋषियों ने प्रार्थना की और उन्हें मुक्त करने का प्रयास किया, और अरुणा नाम की एक धारा का निर्मल जल उनमें मिला दिया। सरस्वती का जल फिर से शुद्ध बहने लगा।",
 "3bdc1ada": "अब भूखे राक्षस हाथ जोड़कर ऋषियों के पास आए। “हम भूखे हैं, और अपने ही पिछले पापों के कारण राक्षस हैं। कृपया हमारी सहायता कीजिए।” दयालु ऋषियों ने उन्हें एक उपाय बताया: अरुणा और सरस्वती के संगम पर स्नान करके वे अपने राक्षस शरीरों से मुक्त हुए और स्वर्ग चले गए।",
 "db5e78d3": "सरस्वती ऋग्वेद की महान नदी है। आज वह धरती के ऊपर नहीं बहती; बहुत लोग मानते हैं कि उसका पुराना मार्ग हरियाणा, पंजाब और राजस्थान में सूखे घग्गर–हकरा नदी तल के साथ-साथ है।",
 "f6a52273": "महाभारत, शल्य पर्व (गदा पर्व), बलराम की तीर्थयात्रा — क्रिटिकल एडिशन में अध्याय 41 (कई छपे संस्करणों में 42)।",
 "f2cd2898": "वसिष्ठ से ईर्ष्या के कारण विश्वामित्र ने सरस्वती नदी को आदेश दिया कि वसिष्ठ को ले आए ताकि वे उन्हें मार सकें।",
 "14667bcc": "नदी उन्हें ले आई — और फिर सुरक्षित वापस बहा ले गई।",
 "551e5240": "विश्वामित्र ने उसे एक वर्ष तक खून के साथ बहने का श्राप दिया, जब तक ऋषियों ने अरुणा से उसे शुद्ध नहीं किया।",
 "4211a306": "सरस्वती दो शक्तिशाली ऋषियों के बीच फँस गई थीं। उन्होंने आदेश मानने और फिर भी सही काम करने का रास्ता निकाला। क्या आप कभी दो लोगों के बीच फँसे हैं? आपने कैसे चुना?",
 "4d60b525": "कल्माषपाद और वसिष्ठ के पुत्र",
 "5df95397": "यह विश्वामित्र के बारे में कही जाने वाली सबसे अंधकारमय कथा है। इसे महाभारत में एक गंधर्व अर्जुन को सुनाता है, यह समझाने के लिए कि वसिष्ठ कौन थे। इसे पढ़ना कठिन है। पर यह उनके जीवन का हिस्सा है, और महाभारत इसे नहीं छिपाता — इसलिए हम भी नहीं छिपाएँगे।",
 "d4658b74": "इक्ष्वाकु वंश में {kalmashapada|कल्माषपाद} नाम का एक राजा था, जिसे सौदास भी कहते थे। वसिष्ठ और विश्वामित्र दोनों उसके कुल-पुरोहित बनना चाहते थे। एक दिन शिकार से थका और भूखा राजा वन के एक तंग रास्ते पर चल रहा था, तभी उसे सामने से आते {shakti|शक्ति} मिले, वसिष्ठ के सबसे बड़े पुत्र। रास्ते में केवल एक के निकलने की जगह थी।",
 "19ff1fc0": "“मेरे रास्ते से हटो,” राजा ने कहा। “नहीं,” शक्ति ने शांत होकर कहा, “यह मेरा रास्ता है। सनातन धर्म के अनुसार राजा ब्राह्मण को रास्ता देता है।” दोनों में से कोई भी नहीं हटा। गुस्से में राजा ने शक्ति को कोड़े से मारा। दर्द और क्रोध से जलते हुए शक्ति ने उसे श्राप दिया: “तुमने एक ऋषि को राक्षस की तरह मारा है, इसलिए तुम राक्षस बन जाओ — मनुष्य का मांस खाने वाले!”",
 "31d5928f": "विश्वामित्र पास ही थे और उन्होंने सब देखा। महाभारत साफ़ कहता है कि यहाँ उन्हें वसिष्ठ के विरुद्ध अपना मौका दिखा। उन्होंने किंकर नाम के एक राक्षस को राजा के शरीर में घुसने की आज्ञा दी। राक्षस उसमें घुस गया, और राजा का मन अंधकार से भर गया।",
 "aaf1acc2": "थोड़े दिन बाद एक भूखा ब्राह्मण राजा के पास आया और मांस वाला भोजन माँगा। राजा ने वचन दिया, फिर भूल गया। आधी रात को उसे याद आया और उसने अपने रसोइए से ब्राह्मण के लिए भोजन ले जाने को कहा। रसोइए के पास मांस नहीं था। “तो उसे मनुष्य का मांस परोस दो,” राक्षस के वश में हुए राजा ने कहा। ब्राह्मण ने अपनी थाली में देखा और राजा को भी श्राप दे दिया: “तुमने मुझे मनुष्य का मांस परोसा है, इसलिए तुम्हें ख़ुद इसकी भूख लगेगी!”",
 "f0d006bc": "दो बार श्राप पाकर और राक्षस के वश में होकर राजा नरभक्षी बन गया। वन में उसकी फिर शक्ति से भेंट हुई। “तुम्हारे श्राप ने मुझे ऐसा बनाया है,” उसने कहा। “इसलिए मैं तुम्हीं से शुरू करूँगा।” और उसने शक्ति को मारकर खा लिया, जैसे बाघ अपने शिकार को खाता है।",
 "d1412929": "और फिर — महाभारत कहता है — विश्वामित्र के उकसाने पर उस राक्षस-राजा ने वसिष्ठ के बाकी सभी पुत्रों को एक-एक करके ढूँढ़ा और उन्हें ऐसे खा गया जैसे शेर छोटे हिरणों को खा जाता है।",
 "d9ba8407": "वसिष्ठ को पता चला कि उनके सौ के सौ पुत्र मारे गए हैं, और यह विश्वामित्र के कारण हुआ है। उनमें पूरे कौशिक वंश को जलाकर राख कर देने की शक्ति थी। पर उन्होंने ऐसा नहीं किया। महाभारत कहता है कि उन्होंने अपना दुःख ऐसे सहा जैसे धरती पर्वतों का भार सहती है — और उन्होंने विश्वामित्र के विरुद्ध कभी हाथ नहीं उठाया।",
 "99d5b0e8": "इसके बजाय, दुःख से टूटकर उन्होंने अपना जीवन ख़त्म करना चाहा। वे मेरु पर्वत की चोटी से कूद पड़े — और चट्टानों पर ऐसे धीरे से गिरे जैसे रुई के ढेर पर। वे धधकती हुई जंगल की आग में चले गए — और आग ने उन्हें नहीं जलाया। उन्होंने गले में भारी पत्थर बाँधकर समुद्र में छलाँग लगा दी — और लहरें उन्हें वापस किनारे पर ले आईं।",
 "7a15ae9d": "उन्होंने ख़ुद को रस्सियों से कसकर बाँधा और बारिश से उफनती एक नदी में कूद पड़े। नदी ने उनके सारे बंधन काट दिए और उन्हें किनारे पर रख दिया — तब से वह नदी विपाशा कहलाई, “बंधनों से छुड़ाने वाली।” वे एक और बड़ी नदी में कूदे; आग की तरह दमकते ऋषि को देखकर वह नदी सौ धाराओं में बँटकर उनसे दूर भाग गई — और वह शतद्रु कहलाई, “सौ धाराओं वाली।” मृत्यु ने उन्हें नहीं लिया।",
 "c494e09a": "विपाशा आज की ब्यास नदी है, और शतद्रु सतलुज — दोनों पंजाब और हिमाचल प्रदेश में बहती हैं।",
 "a961ecc4": "वसिष्ठ अपने सूने आश्रम की ओर लौट चले। चलते हुए उन्हें पीछे से वेदों का पाठ सुनाई दिया, बिलकुल शुद्ध। वे मुड़े। वहाँ उनके पुत्र शक्ति की युवा विधवा अदृश्यंती के सिवा कोई नहीं था, जो उनके पीछे-पीछे आ रही थी। “कौन पाठ कर रहा है?” उन्होंने पूछा। “मेरे गर्भ में पल रहा बच्चा,” उसने कहा। “वह बारह साल से मेरे भीतर वेदों का पाठ कर रहा है।” वसिष्ठ का हृदय आनंद से भर गया। “तो मेरा वंश ख़त्म नहीं हुआ।” उन्होंने मरने की इच्छा छोड़ दी।",
 "7b917bb9": "तभी वन में राक्षस-राजा कल्माषपाद उन्हें खाने के लिए उन पर झपटा। अदृश्यंती चीख उठी। वसिष्ठ उसके आगे खड़े हो गए, एक ही हुंकार से राजा को रोक दिया, मंत्रों से पवित्र किया हुआ जल उस पर छिड़का — और उसे श्राप से और राक्षस से मुक्त कर दिया। राजा होश में आया, लज्जित हुआ, और वसिष्ठ के चरणों में झुक गया। वसिष्ठ ने — जिनके पुत्रों को इसी व्यक्ति ने खाया था — उसे क्षमा कर दिया और फिर से उसके पुरोहित बन गए। महाभारत आगे बताता है कि राजा का कोई उत्तराधिकारी नहीं था, इसलिए उसने वसिष्ठ से नियोग की पुरानी प्रथा से अपनी रानी मदयंती को पुत्र देने की प्रार्थना की; वसिष्ठ ने ऐसा किया, और बालक का नाम अश्मक रखा गया।",
 "db612632": "अदृश्यंती के पुत्र का जन्म हुआ: {parashara|पराशर}। बड़े होकर जब उन्हें पता चला कि उनके पिता की मृत्यु कैसे हुई थी, तो उन्होंने संसार के सारे राक्षसों को जलाने के लिए एक बड़ा अग्नि-यज्ञ शुरू किया। वसिष्ठ और दूसरे ऋषियों ने उन्हें समझाकर रोका, और उन्होंने वह अग्नि हिमालय के उत्तर के वनों में छोड़ दी। आगे चलकर पराशर व्यास के पिता बने, जिन्होंने हमें स्वयं महाभारत दिया।",
 "cdf99154": "महाभारत, आदि पर्व (चैत्ररथ पर्व) — क्रिटिकल एडिशन में अध्याय 166–173, गंधर्व अंगारपर्ण द्वारा अर्जुन को सुनाई गई। रामायण में यह कथा नहीं है; रामायण में वसिष्ठ के पुत्रों को विश्वामित्र त्रिशंकु के यज्ञ के कारण श्राप देते हैं (अध्याय 4)।",
 "b9c58b44": "शक्ति ने {kalmashapada|कल्माषपाद} को नरभक्षी होने का श्राप दिया; विश्वामित्र ने उसमें एक राक्षस घुसा दिया।",
 "af2d9c54": "राजा ने शक्ति को और वसिष्ठ के सभी पुत्रों को मारकर खा लिया।",
 "c0ed7314": "वसिष्ठ ने कभी बदला नहीं लिया। उन्होंने राजा को मुक्त किया, उसे क्षमा किया, और अपने पोते {parashara|पराशर} के लिए जीते रहे।",
 "d7681048": "विश्वामित्र के पास बड़ी शक्ति थी और उन्होंने उसका उपयोग चोट पहुँचाने में किया। वसिष्ठ के पास भी बड़ी शक्ति थी, पर सब कुछ खो देने के बाद भी उन्होंने उसका उपयोग करने से इनकार किया। किसमें ज़्यादा बल चाहिए?",
 "bcea4862": "हरिश्चंद्र — वह राजा जो झूठ नहीं बोलता था",
 "91c8b482": "त्रिशंकु के पुत्र {harishchandra|हरिश्चंद्र} अयोध्या के राजा बने। वे तीनों लोकों में एक बात के लिए प्रसिद्ध थे: उन्होंने कभी झूठ नहीं बोला। देवी भागवत कहता है कि एक दिन इंद्र की सभा में वसिष्ठ ने हरिश्चंद्र को जीवित मनुष्यों में सबसे सच्चा बताया — और अपने पुराने प्रतिद्वंद्वी से यह प्रशंसा सुनकर विश्वामित्र ने घोषणा की कि वे इसे ग़लत साबित करेंगे।",
 "4955918a": "मार्कंडेय पुराण बताता है कि यह कैसे शुरू हुआ। एक दिन वन में शिकार करते हुए हरिश्चंद्र ने स्त्रियों को रोते सुना, “बचाओ! बचाओ!” राजा होने के नाते वे आवाज़ की ओर दौड़े और चिल्लाए, “मेरे राज में कौन अन्याय करने की हिम्मत कर रहा है?” पर वह पुकार विद्याओं की थी — महान विद्याएँ — जिन्हें विश्वामित्र तपस्या से सिद्ध कर रहे थे, और जो बँधना नहीं चाहती थीं। राजा की क्रोध भरी पुकार से ऋषि का ध्यान टूट गया, और विद्याएँ हाथ से निकल गईं।",
 "51cb69b7": "विश्वामित्र क्रोध से उठ खड़े हुए। हरिश्चंद्र ने काँपते हुए प्रणाम किया और कहा, “राजा का कर्तव्य है रक्षा करना, युद्ध करना और दान देना। मुझे क्षमा कीजिए। मुझसे कुछ भी माँग लीजिए।” “तो मुझे राजा के योग्य दान दो,” विश्वामित्र ने कहा। “मुझे अपना पूरा राज्य दे दो — धरती, उसके नगर, उसकी सेना, उसका ख़ज़ाना — सब कुछ, सिवाय तुम्हारे अपने शरीर, तुम्हारी पत्नी, तुम्हारे पुत्र और तुम्हारे धर्म के।” हरिश्चंद्र ने ज़रा भी नहीं हिचकिचाया। “यह आपका हुआ।”",
 "c9f16d00": "“ठीक है,” विश्वामित्र ने कहा। “अब मुझे दक्षिणा दो — वह शुल्क जो किसी बड़े दान के बाद हमेशा देना होता है। उसके बिना दान अधूरा है।” पर हरिश्चंद्र अभी-अभी अपना सब कुछ दे चुके थे। “मुझे एक महीना दीजिए,” उन्होंने कहा, “मैं चुका दूँगा।” “एक महीना,” ऋषि ने कहा। “अब मेरे राज्य से निकल जाओ।”",
 "5a5f4e2d": "राजा पैदल ही अयोध्या से निकल पड़े, अपनी रानी {chandramati|चंद्रमती} के साथ — जिन्हें पुराण शैब्या कहते हैं — और अपने छोटे बेटे {lohitashva|लोहितास्य} के साथ, जिसे पुराण रोहिताश्व कहते हैं। लोग रोते हुए उनके पीछे चले। रानी को पैदल चलने की आदत नहीं थी, वे धीरे-धीरे चल रही थीं — और मार्कंडेय पुराण कहता है कि विश्वामित्र ने उन्हें जल्दी चलाने के लिए अपने डंडे से मारा। हरिश्चंद्र ने देखा, और गुस्से में एक शब्द नहीं कहा।",
 "58adbc68": "वे शिव की पवित्र नगरी काशी गए — जो, पुराण कहता है, किसी धरती के राजा की नहीं है, इसलिए वह उनके दिए हुए राज्य का हिस्सा नहीं थी। तेलुगु कथाओं में विश्वामित्र ने पैसा वसूलने के लिए अपने शिष्य नक्षत्रक को साथ भेजा, जो रास्ते में हर दिन उन्हें तंग करता रहा। महीने के आख़िरी दिन विश्वामित्र हरिश्चंद्र के सामने आ खड़े हुए। “अभी चुकाओ — या कह दो कि नहीं चुका सकते, और मान लो कि तुम्हारा वचन झूठा था।”",
 "f0d26a9c": "चंद्रमती ने बात कही। “स्वामी, अपना वचन मत तोड़िए। पत्नी पति के भले के लिए होती है। मुझे बेच दीजिए, और ऋषि का ऋण चुका दीजिए।” ये शब्द सुनकर हरिश्चंद्र बेहोश हो गए। पर कोई और रास्ता नहीं था। काशी के बाज़ार में उन्होंने अपनी रानी को एक बूढ़े ब्राह्मण के हाथ — तेलुगु कथा में कालकौशिक — घर की दासी के रूप में बेच दिया। जब उन्हें ले जाया जा रहा था, उनका छोटा बेटा उनसे लिपट गया और छोड़ ही नहीं रहा था। इसलिए ब्राह्मण ने बालक को भी ख़रीद लिया।",
 "0c7896ee": "हरिश्चंद्र ने सारा धन विश्वामित्र को दे दिया। ऋषि ने उसे देखा और कहा, “यह काफ़ी नहीं है।” तब हरिश्चंद्र ने अपने पास बची आख़िरी चीज़ बेच दी — ख़ुद को। ख़रीदने वाला एक ही था: काशी के श्मशान का रखवाला एक चांडाल — तेलुगु कथा में वीरबाहु। हरिश्चंद्र उसके सेवक बन गए। उनका काम था: श्मशान की रखवाली करना, और अपने मृतकों का दाह करने आने वाले हर परिवार से शुल्क और कफ़न का एक टुकड़ा लेना।",
 "77526b29": "अयोध्या के राजा जलती चिताओं के बीच रहने लगे — बालों में राख, तन पर चिथड़े, जो बचा-खुचा मिले वही खाते। दिन पर दिन, साल पर साल। फिर भी उन्होंने न झूठ बोला, न अपने मालिक का एक सिक्का भी मारा।",
 "d0628e4e": "एक दिन छोटा लोहितास्य दूसरे लड़कों के साथ अपने मालिक के लिए फूल और दर्भ घास लाने वन में गया। एक साँप ने उसे डस लिया, और उसकी मृत्यु हो गई। उस रात चंद्रमती अपने बेटे का शव अकेले, रोती हुई, श्मशान ले आईं — उनके पास देने को कुछ भी नहीं था।",
 "8378e64d": "श्मशान के रखवाले ने उन्हें रोका। “शुल्क दिए बिना यहाँ कोई शव नहीं जलाता।” वे दुःख में रो पड़ीं, और उनकी आवाज़ से, उनकी बातों से, उसने उन्हें पहचान लिया — और फिर उसे पता चला कि मरा हुआ बच्चा उसका अपना बेटा है। हरिश्चंद्र ज़मीन पर गिर पड़े। पर जब उठे, तो बोले: “फिर भी, मैं एक सेवक हूँ। शुल्क मेरे मालिक का है। उसके बिना मैं तुम्हें इसे जलाने नहीं दे सकता।” चंद्रमती के पास कुछ नहीं था — केवल वह एक वस्त्र जो उन्होंने पहन रखा था। वे उसे देने के लिए उसे आधा फाड़ने लगीं।",
 "de6258ac": "दोनों ने तय किया कि अब वे और नहीं जी सकते। वे अपने बेटे को चिता पर रखेंगे और उसके साथ आग में प्रवेश करेंगे। हरिश्चंद्र ने आँखें बंद कीं और मन को हरि पर टिका दिया। उसी क्षण आकाश प्रकाश से भर गया।",
 "079d74e3": "स्वयं {dharma|धर्म} प्रकट हुए — क्योंकि जिस चांडाल ने हरिश्चंद्र को ख़रीदा था, वह शुरू से वेश बदले हुए धर्म ही थे। {indra|इंद्र} सब देवताओं के साथ आए, और उनके साथ विश्वामित्र भी। इंद्र ने बालक पर अमृत छिड़का, और लोहितास्य ऐसे जाग उठा जैसे नींद से उठा हो। आकाश से फूल बरसने लगे।",
 "a9e94226": "“तुमने सत्य से तीनों लोक जीत लिए हैं,” इंद्र ने राजा से कहा। “अपनी पत्नी और पुत्र के साथ स्वर्ग चलो।” पर हरिश्चंद्र ने कहा, “अपनी प्रजा के बिना मैं स्वर्ग नहीं जाऊँगा। जब मैंने अयोध्या छोड़ी थी, वे मेरे लिए रोए थे। अगर मेरा कोई पुण्य है, तो उसमें उनका भी हिस्सा हो।” और इस तरह, पुराण कहता है, पूरी अयोध्या नगरी अपने राजा के साथ स्वर्ग चली गई। विश्वामित्र ने युवा लोहितास्य को धरती पर राजा बनाया, और सब कुछ लौटा दिया।",
 "9e30c123": "यह कथा तेलुगु में ख़ास तौर पर प्रिय है। गौरन ने 15वीं शताब्दी में “हरिश्चंद्रोपाख्यानमु” लिखा, और सत्य हरिश्चंद्र नाटक पीढ़ियों से आंध्र के गाँवों में खेला जाता रहा है। काशी के श्मशान वाला प्रसिद्ध दृश्य इसी से आता है। “सत्य हरिश्चंद्र” कहावत आज भी ऐसे व्यक्ति के लिए कही जाती है जो झूठ नहीं बोलता।",
 "13e66c77": "महात्मा गांधी ने लिखा कि बचपन में हरिश्चंद्र का नाटक देखकर उन पर गहरा असर हुआ — उन्होंने ख़ुद से पूछा, “सब लोग हरिश्चंद्र की तरह सच्चे क्यों न हों?”",
 "eed63a47": "दो पक्षियों का युद्ध",
 "9ea5c226": "मार्कंडेय पुराण एक और दृश्य जोड़ता है। इस पूरे समय वसिष्ठ बारह साल से गंगा के जल के नीचे तपस्या कर रहे थे। जब वे बाहर आए और सुना कि विश्वामित्र ने हरिश्चंद्र के साथ क्या किया — उस वंश के राजा के साथ जिसकी वसिष्ठ सेवा करते थे — तो वे क्रोध से भर गए। “इस ब्राह्मण-द्वेषी ने एक सच्चे राजा को बर्बाद कर दिया। यह बगुला बन जाए!” उन्होंने श्राप दिया।",
 "bec8faaa": "विश्वामित्र ने तुरंत उलटा श्राप दिया: “और तुम आडी पक्षी बन जाओ!” दोनों महान ऋषि दो विशाल पक्षी बन गए — एक बगुला और एक आडी — और आकाश में लड़ने लगे। उनके पंखों से आँधियाँ उठीं; पर्वत गिर पड़े, समुद्र उफन पड़े, धरती झुक गई और लोक काँप उठे। आख़िर में {brahma|ब्रह्मा} देवताओं के साथ आए, श्राप हटाए, उनके असली रूप लौटाए, और उन्हें गले मिलवाया। “यह बंद करो,” उन्होंने कहा। “हरिश्चंद्र स्वर्ग जा चुके हैं। तुम्हारा झगड़ा संसार को नष्ट कर रहा है।”",
 "dc60fb68": "मार्कंडेय पुराण, अध्याय 7–9 (हरिश्चंद्र, और आडी–बक युद्ध)। देवी भागवत, स्कंध 7, अध्याय 18–27। तेलुगु: गौरन का हरिश्चंद्रोपाख्यानमु, जिससे चंद्रमती, लोहितास्य, नक्षत्रक, कालकौशिक और वीरबाहु नाम परिचित हैं।",
 "b8d1c96b": "{harishchandra|हरिश्चंद्र} ने विश्वामित्र को अपना पूरा राज्य दे दिया, फिर शुल्क चुकाने के लिए अपनी पत्नी, अपने पुत्र और ख़ुद को बेच दिया।",
 "6d23c77a": "अपने ही बेटे के अंतिम संस्कार में भी उन्होंने न अपना कर्तव्य तोड़ा, न अपना वचन।",
 "ca858f24": "धर्म, इंद्र और विश्वामित्र प्रकट हुए; बालक जी उठा, और हरिश्चंद्र अपनी पूरी प्रजा के साथ स्वर्ग गए।",
 "d77fb068": "विश्वामित्र ने हरिश्चंद्र की परीक्षा लगभग मनुष्य की सहने की सीमा से भी आगे तक ली। क्या वह परीक्षा उचित थी? और इससे हमें क्या पता चलता है कि कथा राजा के सत्य के लिए याद की जाती है, ऋषि की क्रूरता के लिए नहीं?",
 "51eb6cf3": "गालव के आठ सौ घोड़े",
 "99edab60": "महाभारत में, महायुद्ध से ठीक पहले, ऋषि नारद दुर्योधन को हठ के ख़तरे से सावधान करने के लिए एक कथा सुनाते हैं। यह विश्वामित्र के शिष्य {galava|गालव} की कथा है।",
 "ff6d32ea": "एक बार स्वयं {dharma|धर्म} विश्वामित्र की परीक्षा लेने आए, वसिष्ठ का वेश बनाकर, और बोले, “मुझे भूख लगी है। मुझे भोजन दो।” विश्वामित्र ने जल्दी-जल्दी बड़ी सावधानी से चावल पकाए। पर उनके पूरा करने से पहले ही अतिथि चले गए और दूसरे ऋषियों का दिया हुआ भोजन खा लिया। जब विश्वामित्र भाप उठता बर्तन लेकर लौटे, तो अतिथि ने कहा, “मैं खा चुका हूँ। यहीं रुको।” और वे चले गए।",
 "d722c198": "तो विश्वामित्र प्रतीक्षा करते रहे। वे चावल का बर्तन सिर पर रखे, केवल हवा पर जीते हुए, सौ साल तक बिलकुल स्थिर खड़े रहे। यह वही व्यक्ति थे जो कभी पल भर के गुस्से में लोगों को श्राप दे देते थे। अब उन्होंने बर्तन नीचे तक नहीं रखा। उनका युवा शिष्य गालव उन सारे सालों में उनके पास खड़ा रहा, प्रेम से उनकी सेवा करता रहा।",
 "30ea9d94": "सौ साल बाद धर्म लौटे, अब भी वसिष्ठ के रूप में, और चावल खाए — जो अब भी गरम और ताज़ा थे। “ब्रह्मर्षि, मैं तुमसे प्रसन्न हूँ,” उन्होंने कहा, और चले गए।",
 "ade93907": "विश्वामित्र ने स्नेह से गालव की ओर देखा। “तुमने मेरी अच्छी सेवा की है। पुत्र, मेरे आशीर्वाद के साथ अब तुम जा सकते हो।” पर गालव ने प्रसन्न और कृतज्ञ होकर पूछा, “मैं आपको क्या गुरुदक्षिणा दूँ?” शिष्य अपनी पढ़ाई के अंत में गुरु को हमेशा कुछ भेंट देता है।",
 "d5c1a804": "“तुम्हारी सेवा ही दक्षिणा थी। जाओ,” विश्वामित्र ने कहा। पर गालव ने फिर पूछा। फिर से। और फिर से। आख़िर विश्वामित्र का धीरज टूट गया। “ठीक है! मुझे आठ सौ घोड़े लाकर दो, चाँद जैसे सफ़ेद, हर एक का एक कान काला। अब जाओ — और देर मत करना!”",
 "60dd6072": "गालव सन्न रह गए। वे एक ग़रीब शिष्य थे। ऐसा एक घोड़ा भी कहाँ से लाते? चिंता से वे दुबले और पीले पड़ गए, न खा पाते, न सो पाते, और यहाँ तक कि प्राण त्यागने की भी सोचने लगे। तब उनके मित्र, पक्षियों के राजा {garuda|गरुड़}, उनके पास आए। “निराश मत हो। मेरी पीठ पर चढ़ो। हम कोई रास्ता निकाल लेंगे।”",
 "77a0f105": "चारों दिशाओं में लंबी यात्राओं के बाद गरुड़ गालव को महान राजा {yayati|ययाति} के पास ले गए। ययाति उदार थे, पर उनके पास न ऐसे घोड़े थे, न अब बहुत धन बचा था। वे किसी ब्राह्मण को ख़ाली हाथ नहीं लौटाना चाहते थे। इसलिए उन्होंने गालव को अपनी बेटी {madhavi|माधवी} दे दी। “राजा उसके लिए कन्या-मूल्य में अपना राज्य तक दे देंगे,” उन्होंने कहा। “घोड़े तो ज़रूर देंगे।”",
 "23f8f47b": "माधवी को एक ऋषि से वरदान मिला था: हर बार संतान को जन्म देने के बाद वह फिर से कुमारी हो जाएगी। गालव उसे पहले अयोध्या के राजा हर्यश्व के पास ले गए, जो पुत्र के लिए तरस रहे थे पर जिनके पास ऐसे केवल दो सौ घोड़े थे। हर्यश्व ने सारे दो सौ दे दिए, और माधवी ने उन्हें एक पुत्र दिया, वसुमना। फिर गालव उसे काशी के राजा दिवोदास के पास ले गए — दो सौ घोड़े, और एक पुत्र, प्रतर्दन। फिर भोज के राजा उशीनर के पास — दो सौ घोड़े, और एक पुत्र, शिबि, जो आगे चलकर एक कबूतर को बचाने के लिए अपना ही मांस देने के लिए प्रसिद्ध हुए।",
 "9e8f4b4f": "छह सौ घोड़े। दो सौ अभी बाक़ी थे। तब गरुड़ ने गालव को सच बताया: “और नहीं हैं। संसार में ऐसे केवल एक हज़ार घोड़े थे — वे जिन्हें ऋचीक विश्वामित्र की बहन सत्यवती के कन्या-मूल्य के रूप में वरुण से लाए थे। उन तीन राजाओं ने दो-दो सौ ख़रीदे। बाक़ी चार सौ नदी पार कराते समय वितस्ता नदी में बह गए। और कोई नहीं हैं।”",
 "383c87e4": "तो गालव छह सौ घोड़ों के साथ विश्वामित्र के पास आए — और माधवी के साथ, बाक़ी दो सौ के बदले उसे भेंट करते हुए। विश्वामित्र ने उन्हें देखा और कहा, “गालव, तुम इसे शुरू में ही मेरे पास क्यों नहीं ले आए? तब तो मैं ख़ुद इससे चार पुत्र पा सकता था।” उन्होंने उसे स्वीकार किया, और माधवी ने विश्वामित्र को एक पुत्र दिया, अष्टक। विश्वामित्र ने अष्टक को राजा बनाया, उसे छह सौ घोड़े दिए, और वन लौट गए। गालव का ऋण चुक गया।",
 "14144a10": "गालव ने माधवी को उसके पिता को लौटा दिया। ययाति ने उसके लिए स्वयंवर रखा, जहाँ वह अपनी पसंद का कोई भी पति चुन सकती थी। राजा और राजकुमार, देवता और नाग आए। माधवी उन सबके सामने से गुज़र गई — और उसने वन को चुना। उसने बाक़ी जीवन वहीं एक स्वतंत्र तपस्विनी की तरह बिताया, हिरणों के साथ घूमते हुए।",
 "06e5dee2": "माधवी के चार पुत्रों — वसुमना, प्रतर्दन, शिबि और अष्टक — ने बाद में अपने नाना ययाति को बचाया, जब वे स्वर्ग से गिरे, अपने अच्छे कर्मों का पुण्य उन्हें देकर। वह कथा महाभारत में इसके ठीक बाद आती है।",
 "2ed5d150": "महाभारत, उद्योग पर्व (भगवद्यान पर्व), नारद द्वारा दुर्योधन को सुनाई गई — क्रिटिकल एडिशन में अध्याय 104–119।",
 "83f81969": "धर्म की परीक्षा में विश्वामित्र सौ साल तक चावल का बर्तन सिर पर रखे खड़े रहे।",
 "012129fb": "{galava|गालव} ने दक्षिणा देने की ज़िद की, और उनसे एक काले कान वाले 800 सफ़ेद घोड़े लाने को कहा गया।",
 "15953a87": "{madhavi|माधवी} की मदद से उन्होंने 600 ढूँढ़े; बाक़ी के बदले विश्वामित्र ने उसे स्वीकार किया, और उनका पुत्र अष्टक हुआ।",
 "e4bfa273": "गालव के गुरु ने कहा “तुम्हारी सेवा काफ़ी है” — और गालव ने यह नहीं माना। नारद ने यह कथा हठ के विरुद्ध चेतावनी के रूप में सुनाई। गालव की जगह तुम होते तो क्या करते? और माधवी के साथ जैसा व्यवहार हुआ, और अंत में उसने जो चुना, उसके बारे में तुम क्या सोचते हो?",
 "09ea0b2c": "अकाल और कुत्ते का मांस",
 "6d13723a": "महायुद्ध के बाद जब भीष्म बाणों की शय्या पर लेटे थे, युधिष्ठिर ने उनसे पूछा: “जब विपत्ति आए, और धर्म का पालन ही असंभव लगे, तब अच्छे व्यक्ति को क्या करना चाहिए?” भीष्म ने विश्वामित्र की एक कथा से उत्तर दिया।",
 "816f86ab": "बहुत पहले, त्रेता और द्वापर युगों के बीच, धरती पर बारह साल का भयंकर सूखा पड़ा। इंद्र ने वर्षा नहीं भेजी। नदियाँ सूख गईं, कुएँ ख़ाली हो गए, फ़सलें मर गईं, पशु मर गए। यज्ञ रुक गए। लोग अपने गाँव छोड़कर चले गए; रास्तों पर हड्डियाँ बिछी थीं। भूख में लोग धर्म भूल गए और एक-दूसरे को खाने लगे।",
 "30e68442": "विश्वामित्र भी भूखे मर रहे थे। वे अपनी पत्नी और पुत्र को एक वन में छोड़कर अकेले भटक रहे थे, खाने को कुछ भी ढूँढ़ते हुए। कमज़ोर, मौत के क़रीब, वे आख़िर चांडालों की एक बस्ती में पहुँचे — वे लोग जो गाँवों के बाहर रहते थे, शिकार करते थे और जो मिले वही खाते थे। वह जगह टूटे बर्तनों, कुत्तों की खालों, हड्डियों और सूअरों व गधों की खोपड़ियों से भरी थी।",
 "e55b15d0": "एक झोपड़ी में विश्वामित्र ने अभी-अभी मारे गए एक कुत्ते की जाँघ देखी। उन्होंने सोचा: “मुझे किसी भी तरह जीवित रहना है। प्राण संकट में हों तो मनुष्य सबसे नीचे वाले से भी ले सकता है। चोरी पाप है — पर मर जाना यानी कोई भी धर्म करने का अवसर खो देना। मैं इसे ले लूँगा।” रात को, जब चांडाल सो रहे थे, वे चुपके से झोपड़ी में घुसे।",
 "d1d78e14": "झोपड़ी का मालिक चांडाल जाग गया। “कौन है? मैं जाग रहा हूँ — और मैं तुम्हें मार डालूँगा!” “मैं हूँ — विश्वामित्र,” ऋषि ने कहा। “मुझे मत मारो।” चांडाल उछलकर खड़ा हो गया, उसकी आँखों में आँसू थे, और उसने हाथ जोड़े। “महान ऋषि, आप आधी रात को एक चांडाल की झोपड़ी में क्या कर रहे हैं?”",
 "fd65abbe": "“मैं भूख से मर रहा हूँ,” विश्वामित्र ने कहा, “और मेरी मृत्यु होने वाली है। मैं यह कुत्ते की जाँघ ले जाऊँगा। भूख मनुष्य की लज्जा को नष्ट कर देती है। अग्नि सब कुछ खा जाती है; मैं अब अग्नि जैसा हूँ।”",
 "c16780b6": "तब कुछ अद्भुत हुआ। वह चांडाल — समाज से बाहर रखा गया व्यक्ति — महान ब्रह्मर्षि को धर्म सिखाने लगा। “ऋषिवर, सुनिए। ज्ञानी कहते हैं कि कुत्ता पशुओं में सबसे नीचा है, और उसकी जाँघ कुत्ते का सबसे नीचा अंग। यह ब्राह्मण का भोजन नहीं है। चोरी करना पाप है, और इसे खाना उससे भी बड़ा पाप। जीने का कोई और उपाय ढूँढ़िए। अपनी भूख को अपनी तपस्या नष्ट न करने दीजिए।”",
 "86a74d25": "वे बहुत देर तक बहस करते रहे। विश्वामित्र ने हर बात का उत्तर दिया: “जब प्राण संकट में हों, तब मनुष्य वह कर सकता है जो वह और कभी न करे, और बाद में तपस्या से ख़ुद को शुद्ध कर ले। पहले जीवन है; केवल जीवित ही धर्म का पालन कर सकते हैं। ज़रूरत पड़ने पर स्वयं अगस्त्य ने वातापि राक्षस को खा लिया था। मैं इसे खाऊँगा, और बाद में प्रायश्चित करूँगा।” चांडाल ने कहा, “जो आपको ठीक लगे, वही कीजिए,” और चुप हो गया।",
 "81e1fb20": "भीष्म ने बात पूरी की: “तो, युधिष्ठिर — जब पूरा संसार संकट में हो, तब बुद्धिमान व्यक्ति किसी भी उपाय से अपने प्राण बचाता है, और फिर अच्छे कर्मों से ख़ुद को शुद्ध करता है। यही आपद्धर्म है, संकट के समय का धर्म। यह सामान्य समय के लिए नहीं है।”",
 "dfce0f9f": "यह कथा इतनी प्रसिद्ध थी कि मनुस्मृति एक पंक्ति में इसका उल्लेख करती है, इस उदाहरण के रूप में कि जब प्राण दाँव पर हों तो धर्म कैसे झुकता है: सही-ग़लत जानने वाले विश्वामित्र ने भूख से मरते समय एक चांडाल से कुत्ते की जाँघ ली।",
 "0c5d3875": "देखो, इस कथा में धर्म कौन सिखाता है। न कोई राजा, न कोई ऋषि — वह चांडाल। महाभारत अक्सर ज्ञान की बातें अनपेक्षित लोगों के मुँह से कहलवाता है: एक शिकारी, एक कसाई, एक गृहिणी, एक चांडाल।",
 "4b267f1e": "महाभारत, शांति पर्व (आपद्धर्म पर्व) — क्रिटिकल एडिशन में अध्याय 139 (कई छपे संस्करणों में 141)। मनुस्मृति 10.108।",
 "8777d97a": "बारह साल के अकाल में भूखे विश्वामित्र ने एक चांडाल की झोपड़ी से कुत्ते की जाँघ लेनी चाही।",
 "78797b69": "चांडाल ने उनसे धर्म पर बहस की; विश्वामित्र ने उत्तर दिया कि पहले जीवन बचाना चाहिए।",
 "64340edc": "क्या जीवित रहने के लिए कभी नियम तोड़ना सही है? तुम्हारे विचार से बहस कौन जीता — ऋषि या चांडाल?",
 "b54ce96b": "राम के गुरु, गायत्री के द्रष्टा",
 "8f9b5bf6": "जब हम रामायण में उनसे मिलते हैं, तब तक विश्वामित्र ब्रह्मर्षि बन चुके हैं। एक दिन वे अयोध्या आते हैं और राजा {dasaratha|दशरथ} से ऐसी चीज़ माँगते हैं जो कोई पिता नहीं देना चाहता: उनका पुत्र {rama|राम}, जो अभी सोलह का भी नहीं हुआ, ताकि वह उनके यज्ञ की राक्षसों मारीच और सुबाहु से रक्षा करे।",
 "6ec269de": "दशरथ मना कर देते हैं — और विश्वामित्र की पुरानी आग एक बार फिर भड़क उठती है, जिससे धरती हिल जाती है और देवता काँप उठते हैं। उनके पुराने प्रतिद्वंद्वी {vasishtha|वसिष्ठ} ही राजा को शांत करते हैं: “विश्वामित्र के साथ राम का कोई अहित नहीं हो सकता। वे मनुष्य रूप में धर्म हैं। वे हर अस्त्र जानते हैं। वे अपने यज्ञ की रक्षा ख़ुद कर सकते थे; वे राम को राम के भले के लिए माँग रहे हैं।” इस तरह, अंत में, दोनों महान प्रतिद्वंद्वी राम के लिए मिलकर काम करते हैं।",
 "e91f1b75": "रामायण में पढ़ें: विश्वामित्र राम को माँगते हैं",
 "e6c61ed2": "सरयू के किनारे विश्वामित्र दोनों बालकों को दो मंत्र सिखाते हैं, बला और अतिबला, ताकि उन्हें कभी भूख, प्यास या थकान न लगे। और अगली सुबह वे राम को ऐसे शब्दों से जगाते हैं जो आज भी पूरे भारत के मंदिरों में हर भोर गाए जाते हैं:",
 "4fdb864d": "“कौसल्या के धन्य पुत्र राम, पूर्व में भोर हो रही है। उठो, पुरुषों में सिंह — दिन के पवित्र कर्तव्य करने हैं।” (बाल 23.2)",
 "7542725c": "यह तिरुमला में हर सुबह गाए जाने वाले श्री वेंकटेश सुप्रभातम का सबसे पहला श्लोक है। इस तरह हर दिन भगवान वेंकटेश्वर को विश्वामित्र के शब्दों से जगाया जाता है।",
 "c73a4058": "फिर वे दोनों भाइयों को वन में ले जाते हैं। वे राम से भयंकर {tataka|ताड़का} को मारने को कहते हैं, और जब राम एक स्त्री को मारने में हिचकिचाते हैं, तो वे समझाते हैं कि रक्षक का कर्तव्य रक्षा करना है, हमलावर चाहे कोई भी हो। राम से प्रसन्न होकर वे उन्हें वे सारे दिव्य अस्त्र देते हैं जो उन्होंने कभी शिव से पाए थे — वही अस्त्र जो वसिष्ठ के दंड के सामने विफल हो गए थे, अब उसके हाथों में जो उनका उपयोग केवल धर्म के लिए करेगा।",
 "165db692": "रामायण में पढ़ें: ताड़का",
 "3b49e40d": "उनके सिद्धाश्रम में राम और लक्ष्मण छह दिन और रात यज्ञ की रक्षा करते हैं; राम मारीच को दूर समुद्र में फेंक देते हैं और सुबाहु को मार देते हैं। फिर विश्वामित्र उन्हें मिथिला ले जाते हैं। रास्ते में वे उन्हें उस धरती की कथाएँ सुनाते हैं — अपने परिवार की, गंगा के अवतरण की, समुद्र-मंथन की — और राम को उस आश्रम में ले आते हैं जहाँ {ahalya|अहल्या} का उद्धार होता है।",
 "5058d4c1": "रामायण में पढ़ें: शिव का धनुष और चार विवाह",
 "ae05995a": "हम उन्हें एक बार और देखते हैं: उत्तर कांड में, राम के राज्याभिषेक के बाद, विश्वामित्र उन महान ऋषियों में हैं जो उस राजा को आशीर्वाद देने अयोध्या आते हैं जिसे वे कभी बालक के रूप में वन ले गए थे।",
 "e9562785": "गायत्री के द्रष्टा",
 "f548ce58": "विश्वामित्र का सबसे बड़ा उपहार रामायण से भी पुराना है। ऋग्वेद का तीसरा मंडल — साठ से अधिक सूक्त — विश्वामित्र और उनके परिवार के ऋषियों ने देखा था। और उसी में सबसे पवित्र मंत्र है, जो उपनयन में हर बालक को दिया जाता है, हर संध्या में जपा जाता है: गायत्री। उसके ऋषि विश्वामित्र हैं।",
 "233f4d98": "“हम दिव्य सविता, सूर्य, के उस सबसे श्रेष्ठ तेज का ध्यान करते हैं। वे हमारी बुद्धि को प्रेरित करें।” (ऋग्वेद 3.62.10)",
 "8767efdb": "सोचो: वह राजा जिसने कभी बलपूर्वक एक गाय छीननी चाही, जिसने क्रोध में श्राप दिए, जो कामना में गिरा और फिर उठा, जिसने हज़ारों साल ख़ुद से लड़ते बिताए — यही वह व्यक्ति है जिसके द्वारा संसार को स्पष्ट और जागी हुई बुद्धि की प्रार्थना मिली।",
 "6095100c": "उनके मंडल का एक और सूक्त, ऋग्वेद 3.33, विश्वामित्र और दो नदियों, विपाश और शुतुद्री — ब्यास और सतलुज — के बीच एक संवाद है। वे उनसे अपना जल नीचे करने को कहते हैं ताकि उनके लोग पार जा सकें, और वे मान जाती हैं। ये वही दो नदियाँ हैं जिन्होंने महाभारत में वसिष्ठ को डूबने नहीं दिया था (अध्याय 9)।",
 "f4f6a648": "एक सप्तर्षि",
 "2ecde75a": "पुराण कहते हैं कि हमारे वर्तमान युग, वैवस्वत मनु के युग में, आकाश के सात महान ऋषि — सप्तर्षि — कश्यप, अत्रि, वसिष्ठ, विश्वामित्र, गौतम, जमदग्नि और भरद्वाज हैं। तो विश्वामित्र, जिन्होंने कभी क्रोध में त्रिशंकु के लिए तारों का एक नया समूह बना दिया था, अब ख़ुद सच्चे सप्तर्षियों में चमकते हैं — वसिष्ठ के साथ-साथ।",
 "3c78d2f4": "विश्वामित्र और कौशिक गोत्र के परिवार आज भी अपना वंश उन्हीं से जोड़ते हैं। और उनकी कथा हज़ारों सालों से सुनाया जाने वाला सबसे बड़ा प्रमाण है कि कोई भी व्यक्ति जन्म से या पिछली ग़लतियों से बँधा नहीं है — कि मनुष्य अपने आप को बदल सकता है, अगर वह सबसे लंबी लड़ाई लड़ने को तैयार हो।",
 "7339d847": "बिग डिपर के सात चमकीले तारों को भारतीय परंपरा सप्तर्षि मंडल कहती है। उसमें वसिष्ठ के पास वाला छोटा तारा उनकी पत्नी अरुंधती है।",
 "c5cbbe3a": "वाल्मीकि रामायण, बाल कांड, सर्ग 18–31 और 47–74; उत्तर कांड, सर्ग 1। ऋग्वेद, मंडल 3 (3.33; गायत्री, 3.62.10)। वैवस्वत मन्वंतर के सप्तर्षि: विष्णु पुराण 3.1 और दूसरे पुराण (अलग-अलग ग्रंथों में सूचियाँ थोड़ी अलग हैं)।",
 "9825b8c3": "विश्वामित्र अपने यज्ञ की रक्षा के लिए युवा राम को ले गए, उन्हें बला और अतिबला सिखाईं, और अपने सारे दिव्य अस्त्र दिए।",
 "29fb5118": "“कौसल्या सुप्रजा राम” — राम से कहे उनके शब्दों से वेंकटेश सुप्रभातम शुरू होता है।",
 "41f3cb87": "वे गायत्री मंत्र के ऋषि हैं, और हमारे युग के सात सप्तर्षियों में से एक।",
 "05548ab1": "विश्वामित्र राजा के रूप में जन्मे और ब्रह्मर्षि बने; उन्होंने भयंकर ग़लतियाँ कीं और संसार को गायत्री भी दी। अगर तुम उनसे एक प्रश्न पूछ सको, तो वह क्या होगा?",
 "417fdc10": "कुश",
 "eec5a7c0": "ब्रह्मा के पुत्र और एक महान राजा व तपस्वी। विश्वामित्र का परिवार, कौशिक, उन्हीं के नाम पर है।",
 "51edc241": "कुशनाभ",
 "209fe670": "कुश के पुत्र और महोदय के राजा। सौ बेटियों के और गाधि के पिता — विश्वामित्र के दादा।",
 "4b83ca36": "गाधि",
 "f20a9483": "कान्यकुब्ज के राजा और विश्वामित्र व सत्यवती के पिता।",
 "0806767d": "सत्यवती",
 "de035f98": "विश्वामित्र की बड़ी बहन, ऋषि ऋचीक की पत्नी और परशुराम की दादी। वे कौशिकी नदी बन गईं।",
 "8c8268c0": "ऋचीक",
 "efa388ff": "भृगु वंश के एक ऋषि। उन्होंने सत्यवती से विवाह किया; उनके पुत्र जमदग्नि थे और पोते परशुराम।",
 "57b59922": "जमदग्नि",
 "f984448e": "ऋचीक और सत्यवती के पुत्र, परशुराम के पिता। सात महान ऋषियों (सप्तर्षियों) में से एक।",
 "9c0b2956": "शबला (नंदिनी)",
 "55203fc1": "वसिष्ठ की चितकबरी, मनोकामना पूरी करने वाली गाय, कामधेनु से जन्मी। महाभारत उसे नंदिनी कहता है।",
 "f8bc6ec4": "अंबरीष",
 "68d95969": "अयोध्या के एक राजा, जिनके यज्ञ का पशु इंद्र ने चुरा लिया था।",
 "968e19c1": "शकुंतला",
 "e4d54ac0": "विश्वामित्र और मेनका की बेटी, जिन्हें ऋषि कण्व ने पाला। भरत की माता, जिनके नाम पर भारत का नाम पड़ा।",
 "de41bb54": "कण्व",
 "c48e0c32": "एक ऋषि जो मालिनी नदी के किनारे रहते थे और जिन्होंने शकुंतला को अपनी बेटी की तरह पाला।",
 "2669ac0e": "रंभा",
 "d1a47a16": "इंद्र की सभा की सबसे प्रसिद्ध अप्सरा।",
 "1787444a": "सरस्वती (नदी)",
 "e77dc235": "वेदों की पवित्र नदी, जिसके किनारे वसिष्ठ और विश्वामित्र दोनों ने तपस्या की।",
 "f312f3e1": "कल्माषपाद",
 "727e2a3b": "इक्ष्वाकु वंश के एक राजा, जिन्हें सौदास या मित्रसह भी कहते हैं, जिन्हें नरभक्षी राक्षस बनने का श्राप मिला।",
 "5e0fd6d6": "शक्ति",
 "e75befc4": "वसिष्ठ के सबसे बड़े पुत्र और पराशर के पिता।",
 "8d1f5472": "पराशर",
 "7d607e38": "वसिष्ठ के पोते, शक्ति के पुत्र — और व्यास के पिता।",
 "6e591a7c": "हरिश्चंद्र",
 "4162ceff": "त्रिशंकु के पुत्र और अयोध्या के राजा, जिन्हें हमेशा उस राजा के रूप में याद किया जाता है जो झूठ नहीं बोलता था।",
 "79fe634b": "चंद्रमती (शैब्या)",
 "3c470653": "हरिश्चंद्र की रानी। पुराण उन्हें शैब्या कहते हैं; तेलुगु में वे चंद्रमती हैं।",
 "0d355359": "लोहितास्य (रोहित)",
 "293a8a01": "हरिश्चंद्र और चंद्रमती के पुत्र।",
 "5bf8f2e6": "गालव",
 "3024479e": "विश्वामित्र के समर्पित शिष्य, जिन्होंने अपने गुरु को दक्षिणा देने की ज़िद की।",
 "5a125a97": "गरुड़",
 "dadb6f90": "पक्षियों के राजा और विष्णु के वाहन।",
 "a017e1fa": "माधवी",
 "4c7a263c": "राजा ययाति की बेटी, जिन्हें गालव को उनकी गुरुदक्षिणा चुकाने में मदद के लिए दिया गया।",
 "bfabe6b2": "ययाति",
 "7bcf07be": "चंद्रवंश के एक महान राजा, पांडवों के और श्रीकृष्ण के यादवों के पूर्वज।",
 "ffae391f": "धर्म (यम)",
 "77fec5ce": "धर्म के देवता, जो अक्सर लोगों की परीक्षा लेने के लिए वेश बदलकर आते हैं।",
 "65735c1f": "परशुराम",
 "a3226286": "ऋषि जमदग्नि के पुत्र, फरसा धारण करने वाले विष्णु के अवतार, जिन्होंने एक बार धरती के दुष्ट राजाओं का इक्कीस बार नाश किया और फिर पूरी धरती दान में दे दी।",
 "199e8c3c": "वसिष्ठ",
 "1bd55afa": "वे महान ऋषि जो पीढ़ियों तक इक्ष्वाकु राजाओं के कुलगुरु रहे — शांत, ज्ञानी और बहुत शक्तिशाली।",
 "d6e47a12": "शिव",
 "3211a04b": "योग और तपस्या के महान देवता, जो कैलास पर रहते हैं, अपनी जटाओं में चंद्रमा और गंगा धारण करते हैं, और जिनका तीसरा नेत्र अग्नि का है।",
 "7f233327": "त्रिशंकु",
 "2f7e0764": "इक्ष्वाकु वंश के एक राजा, जो अपने शरीर के साथ ही स्वर्ग जाना चाहते थे। विश्वामित्र ने उनके लिए तारों का एक नया स्वर्ग बनाया।",
 "e1d7d581": "ब्रह्मा",
 "fefd1352": "ब्रह्मांड के चार मुख वाले रचयिता। वे उस कमल पर बैठते हैं जो विष्णु की नाभि से निकलता है।",
 "c016d4b4": "इंद्र",
 "e3cc565b": "देवताओं के राजा और स्वर्ग के स्वामी, जो वज्र धारण करते हैं और सफ़ेद हाथी ऐरावत पर सवार होते हैं।",
 "e99dce69": "शुनःशेप",
 "d6e536de": "ऋषि ऋचीक का एक छोटा बेटा, जिसे विश्वामित्र के मंत्रों ने बचाया।",
 "221ab9d1": "मेनका",
 "2f889ffb": "अप्सराओं में सबसे सुंदर, जिसे इंद्र ने विश्वामित्र की तपस्या भंग करने के लिए भेजा।",
 "62815f3c": "काम (मन्मथ)",
 "2fbdc76c": "प्रेम के देवता, जो लोगों के मन में प्रेम जगाने के लिए फूलों के बाण चलाते हैं। शिव के तीसरे नेत्र से जलकर वे अनंग बन गए — “बिना शरीर वाले”।",
 "b9abcdb5": "राम",
 "d0198694": "अयोध्या के राजकुमार, इक्ष्वाकु वंश में जन्मे — इस कथा के नायक, और मनुष्य रूप में जन्मे स्वयं विष्णु।",
 "553014cd": "लक्ष्मण",
 "23193b74": "सुमित्रा के पुत्र और शत्रुघ्न के जुड़वाँ भाई। बचपन से ही वे राम की छाया थे — हमेशा उनके साथ, अपने धनुष से उनकी रक्षा करते हुए।",
 "3f5677c7": "दशरथ",
 "dc552c4c": "इक्ष्वाकु वंश के अयोध्या के राजा — एक पराक्रमी योद्धा, एक न्यायप्रिय शासक, और राम के पिता।",
 "90b937b8": "ताड़का",
 "57e89ce0": "हज़ार हाथियों के बल वाली एक यक्षिणी। अगस्त्य के श्राप से वह एक भयंकर राक्षसी बन गई जिसने मलद और करूष देशों को उजाड़ दिया।",
 "e68e50c7": "अहल्या",
 "4ed98ef4": "ऋषि गौतम की सुंदर पत्नी। एक ग़लत चुनाव के लिए श्राप पाकर वे राम के आने तक अदृश्य रहकर तपस्या करती रहीं, और पाँच महान स्त्रियों, पंचकन्याओं, में याद की जाती हैं।",
 "32f41fb1": "जनक",
 "70ce09f6": "मिथिला (विदेह) के ज्ञानी राजा, जो अपनी विद्या और वैराग्य के लिए प्रसिद्ध थे — और सीता के पिता।",
 "f5f20df3": "सीता",
 "72cc4340": "राजा जनक की बेटी, जो उन्हें हल चलाते समय धरती की एक कूँड़ में मिलीं। कोमल, साहसी और समर्पित, वे धरती पर जन्मी स्वयं लक्ष्मी हैं।",
});
